}

-- Add "chase" preset to WELD_PRESETS so users can also use pure Follow-Everywhere mode
WELD_PRESETS.chase = {
    offset = CFrame.new(0, 0, 2.2),
    anim15 = nil,
    anim6  = nil,
    animFallbacks = {},
    osc = nil,
    refMode = "torso",
    label = "Auto-Chase (Follow)"
}
end -- end WELD_PRESETS scope

-- Compute a clean, level, upright CFrame relative to a target part/character
getFlatYawCFrame = function(cf, posOverride)
    if not cf then return CFrame.new() end
    local pos = posOverride or cf.Position
    local look = cf.LookVector
    local flatLook = Vector3.new(look.X, 0, look.Z)
    if flatLook.Magnitude > 0.001 then
        return CFrame.lookAt(pos, pos + flatLook.Unit, Vector3.yAxis)
    end
    local _, yYaw, _ = cf:ToEulerAnglesYXZ()
    return CFrame.new(pos) * CFrame.Angles(0, yYaw, 0)
end

-- Cached character lookup to avoid expensive recursive Workspace scans every frame (from khaman_dhokla.lua)
do
local CustomCharLookupCache = {} -- [userId] = { model = Instance, lastScan = number }
local CommonCharContainers = { "Characters", "Players", "Entities", "Live", "Units", "Ingame", "Chars" }
local LastGlobalDeepCharScan = 0
local TargetRefCache = setmetatable({}, { __mode = "k" })

findPlayerCharacterAnywhere = function(plr, skipDeepSearch)
    if not plr then return nil end
    if plr.Character and plr.Character.Parent then
        CustomCharLookupCache[plr.UserId] = { model = plr.Character, lastScan = tick() }
        return plr.Character
    end
    local cached = CustomCharLookupCache[plr.UserId]
    if cached and cached.model and cached.model.Parent then
        return cached.model
    end
    -- Fast top-level & common character container check (O(1), zero lag)
    local direct = workspace:FindFirstChild(plr.Name)
    if direct and direct:IsA("Model") and direct ~= LP.Character then
        CustomCharLookupCache[plr.UserId] = { model = direct, lastScan = tick() }
        return direct
    end
    for _, folderName in ipairs(CommonCharContainers) do
        local folder = workspace:FindFirstChild(folderName)
        local found = folder and folder:FindFirstChild(plr.Name)
        if found and found:IsA("Model") and found ~= LP.Character then
            CustomCharLookupCache[plr.UserId] = { model = found, lastScan = tick() }
            return found
        end
    end
    -- Globally throttled deep search: prevents multi-player recursive workspace scans from ever spiking FPS
    if not skipDeepSearch then
        local now = tick()
        if (now - LastGlobalDeepCharScan) > 2.5 and (not cached or (now - (cached.lastScan or 0)) > 6.0) then
            LastGlobalDeepCharScan = now
            CustomCharLookupCache[plr.UserId] = { model = nil, lastScan = now }
            local byName = workspace:FindFirstChild(plr.Name, true)
            if byName and byName:IsA("Model") and byName ~= LP.Character and (byName:FindFirstChildOfClass("Humanoid") or byName.PrimaryPart or byName:FindFirstChildWhichIsA("BasePart", true)) then
                CustomCharLookupCache[plr.UserId] = { model = byName, lastScan = now }
                return byName
            end
        end
    end
    return plr.Character
end

-- Deep fallback reference part resolver with weak-table caching (zero repeated GetDescendants lag)
pickTargetRef = function(char, mode)
    if not char then return nil end
    local cacheKey = (mode == "head") and "head" or "torso"
    local cEntry = TargetRefCache[char]
    if cEntry and cEntry[cacheKey] and cEntry[cacheKey].Parent and cEntry[cacheKey]:IsDescendantOf(char) then
        return cEntry[cacheKey]
    end
    local resolved = nil
    if mode == "head" then
        local h = char:FindFirstChild("Head") or char:FindFirstChild("head", true)
        if h and h:IsA("BasePart") then
            resolved = h
        else
            for _, desc in ipairs(char:GetDescendants()) do
                if desc:IsA("BasePart") and desc.Name:lower():find("head", 1, true) then
                    resolved = desc
                    break
                end
            end
        end
    end
    if not resolved then
        local hum = char:FindFirstChildOfClass("Humanoid")
        local hrp = char:FindFirstChild("HumanoidRootPart")
            or (hum and hum.RootPart)
            or char.PrimaryPart
            or char:FindFirstChild("UpperTorso")
            or char:FindFirstChild("LowerTorso")
            or char:FindFirstChild("Torso")
            or char:FindFirstChild("Head")
        if hrp and hrp:IsA("BasePart") then
            resolved = hrp
        elseif hum and hum.SeatPart and hum.SeatPart:IsA("BasePart") then
            resolved = hum.SeatPart
        else
            resolved = char:FindFirstChildWhichIsA("BasePart", true)
        end
    end
    if resolved then
        if not cEntry then
            cEntry = {}
            TargetRefCache[char] = cEntry
        end
        cEntry[cacheKey] = resolved
    end
    return resolved
end
end

local function getVerifiedStreamedCFrame(plr)
    if not plr then return nil end
    local char = findPlayerCharacterAnywhere(plr)
    if char and char.Parent then
        local part = pickTargetRef(char, "torso")
        if part and part.Parent then
            local cf = part.CFrame
            if not isLethalVoidCF(cf, part.AssemblyLinearVelocity) then
                PlayerLocationCache[plr.UserId] = { cf = cf, time = tick(), verified = true }
                return cf
            end
        end
    end
    return nil
end

-- Resolve a player's CFrame even when their Character's BaseParts are 100% streamed out by StreamingEnabled! (from khaman_dhokla.lua)
getBestTargetCFrame = function(plr, skipDeepSearch)
    if not plr then return nil end
    local char = findPlayerCharacterAnywhere(plr, skipDeepSearch)
    if char then
        local part = pickTargetRef(char, "torso")
        if part and part.Parent then
            local cf = part.CFrame
            if not isLethalVoidCF(cf, part.AssemblyLinearVelocity) then
                PlayerLocationCache[plr.UserId] = { cf = cf, time = tick(), verified = true }
                return cf
            end
        end
        local okPivot, pivotCF = pcall(function() return char:GetPivot() end)
        if okPivot and pivotCF and pivotCF.Position.Magnitude > 0.5 and not isLethalVoidCF(pivotCF) then
            PlayerLocationCache[plr.UserId] = { cf = pivotCF, time = tick() }
            return pivotCF
        end
        local okWP, wpCF = pcall(function() return char.WorldPivot end)
        if okWP and wpCF and wpCF.Position.Magnitude > 0.5 and not isLethalVoidCF(wpCF) then
            PlayerLocationCache[plr.UserId] = { cf = wpCF, time = tick() }
            return wpCF
        end
    end
    local cached = PlayerLocationCache[plr.UserId]
    if cached and cached.cf and not isLethalVoidCF(cached.cf) then
        return cached.cf
    end
    return nil
end

local function getTargetStreamHintCFrame(plr)
    return getBestTargetCFrame(plr)
end

local function ensureStreamFocusAt(cfOrPos)
    local pos = nil
    if typeof(cfOrPos) == "CFrame" then
        pos = cfOrPos.Position
    elseif typeof(cfOrPos) == "Vector3" then
        pos = cfOrPos
    end
    if not pos then return end
    task.spawn(function()
        pcall(function() LP:RequestStreamAroundAsync(pos, 1) end)
    end)
end

-- Throttled background scanner (2.5Hz, non-recursive) that caches every player's position & pivot without frame lag
do
    local lastScanTick = 0
    RunService.Heartbeat:Connect(function()
        local now = os.clock()
        if now - lastScanTick < 0.40 then return end
        lastScanTick = now
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP then
                pcall(function() getBestTargetCFrame(p, true) end)
            end
        end
    end)
end

-- Active Stream-Piercer & Server Hiding-Spot Seeker (from khaman_dhokla.lua):
-- Instant return when target is already streamed; throttled async stream requests when unstreamed.
streamAndTeleportToTarget = function(targetPlr, refMode, maxWaitSeconds, allowSweepOrOffset)
    if not targetPlr or targetPlr.Parent ~= Players then return nil, nil end
    maxWaitSeconds = math.min(maxWaitSeconds or 0.55, 0.65)
    local allowSweep = (allowSweepOrOffset == true)
    local stepOffset = (typeof(allowSweepOrOffset) == "CFrame") and allowSweepOrOffset or CFrame.new(0, 1.5, 2)
    local myChar = LP.Character
    local myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
    local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
    local originSafeCF = (myRoot and isSafePlayableCF(myRoot.CFrame) and myRoot.CFrame) or LastKnownSafeCF or findFallbackSafeCF()

    -- Fast path: if target's reference part is already streamed in, connect immediately with zero wait!
    local tChar = findPlayerCharacterAnywhere(targetPlr)
    local tHum  = tChar and tChar:FindFirstChildOfClass("Humanoid")
    if tHum and tHum.Health <= 0 then
        return tChar, nil
    end
    local tRef = tChar and pickTargetRef(tChar, refMode or "torso")
    if tRef and tRef.Parent then
        if isLethalVoidCF(tRef.CFrame, tRef.AssemblyLinearVelocity) then
            return tChar, nil
        end
        if myChar and myRoot then
            breakAllSeatsAndExternalJoints(myChar, myHum, myRoot)
            if myHum and myHum.Sit then pcall(function() myHum.Sit = false end) end
            myRoot.Anchored = false
            local destCF = tRef.CFrame * stepOffset
            markIntentionalTeleport(destCF)
            myRoot.AssemblyLinearVelocity = Vector3.zero
            myRoot.AssemblyAngularVelocity = Vector3.zero
            myRoot.CFrame = destCF
        end
        return tChar, tRef
    end

    -- Step 1: Target is in an unstreamed chunk. Request stream around their known/pivot location WITHOUT stripping collision!
    local started = tick()
    local lastStreamCall = 0
    local didTeleportFromOrigin = false
    while tick() - started < maxWaitSeconds do
        if targetPlr.Parent ~= Players then break end
        tChar = findPlayerCharacterAnywhere(targetPlr)
        tHum  = tChar and tChar:FindFirstChildOfClass("Humanoid")
        if tHum and tHum.Health <= 0 then break end
        tRef  = tChar and pickTargetRef(tChar, refMode or "torso")
        if tRef and tRef.Parent then
            if isLethalVoidCF(tRef.CFrame, tRef.AssemblyLinearVelocity) then
                tRef = nil
                break
            end
            myChar = LP.Character
            myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
            myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
            if myChar and myRoot then
                breakAllSeatsAndExternalJoints(myChar, myHum, myRoot)
                if myHum and myHum.Sit then pcall(function() myHum.Sit = false end) end
                myRoot.Anchored = false
                local destCF = tRef.CFrame * stepOffset
                markIntentionalTeleport(destCF)
                myRoot.AssemblyLinearVelocity = Vector3.zero
                myRoot.AssemblyAngularVelocity = Vector3.zero
                myRoot.CFrame = destCF
            end
            return tChar, tRef
        end
        local targetCF = getBestTargetCFrame(targetPlr)
        if targetCF and isSafePlayableCF(targetCF) then
            local now = tick()
            if now - lastStreamCall > 0.20 then
                lastStreamCall = now
                task.spawn(function()
                    pcall(function() LP:RequestStreamAroundAsync(targetCF.Position, 1.0) end)
                end)
            end
            if allowSweep then
                myChar = LP.Character
                myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
                if myRoot then
                    didTeleportFromOrigin = true
                    moveState.lastTeleportTick = tick()
                    myRoot.AssemblyLinearVelocity = Vector3.zero
                    myRoot.AssemblyAngularVelocity = Vector3.zero
                    myRoot.CFrame = targetCF * CFrame.new(0, 2, 0)
                end
            end
        else
            break
        end
        RunService.Heartbeat:Wait()
    end

    tChar = findPlayerCharacterAnywhere(targetPlr)
    tHum  = tChar and tChar:FindFirstChildOfClass("Humanoid")
    tRef  = (not (tHum and tHum.Health <= 0)) and tChar and pickTargetRef(tChar, refMode or "torso") or nil
    if tRef and tRef.Parent and not isLethalVoidCF(tRef.CFrame, tRef.AssemblyLinearVelocity) then
        myChar = LP.Character
        myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
        myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
        if myChar and myRoot then
            breakAllSeatsAndExternalJoints(myChar, myHum, myRoot)
            if myHum and myHum.Sit then pcall(function() myHum.Sit = false end) end
            myRoot.Anchored = false
            local destCF = tRef.CFrame * stepOffset
            markIntentionalTeleport(destCF)
            myRoot.AssemblyLinearVelocity = Vector3.zero
            myRoot.AssemblyAngularVelocity = Vector3.zero
            myRoot.CFrame = destCF
        end
        return tChar, tRef
    end

    -- Target could not be streamed or is in the void: restore local player cleanly to originSafeCF so we NEVER get stranded!
    if didTeleportFromOrigin and LP.Character then
        recoverCharacterState(LP.Character, originSafeCF)
    end
    return tChar, nil
end

local getNearestPlayer
do
    local ProximityPromptService = nil
    pcall(function() ProximityPromptService = game:GetService("ProximityPromptService") end)

    -- Tracks players recently interacted with or carried via ProximityPrompt or Interact/Carry UI buttons
    local InteractedCarryPlayers = {} -- [userId] = { triggeredAt = number, lastNearAt = number }

    local CARRY_INTERACT_KEYWORDS = {
        "carry", "carried", "carrying", "carrier",
        "interact", "interacting", "interaction",
        "piggyback", "cradle", "shoulder", "bridal",
        "hug", "hugging", "cuddle", "hold", "holding", "held",
        "grab", "grabbed", "grabbing", "pickup", "pick up", "lift",
        "sync", "synced", "couple", "coupled", "partner", "paired", "duet",
        "weld", "welded", "attached", "linked"
    }

    local RELEASE_KEYWORDS = {
        "drop", "release", "put down", "putdown", "uncarry", "stop carry", "stop interact", "let go", "detach"
    }

    local function textMatchesAny(str, wordList)
        if type(str) ~= "string" or str == "" then return false end
        local low = str:lower()
        for i = 1, #wordList do
            if low:find(wordList[i], 1, true) then
                return true
            end
        end
        return false
    end

    local function getPlayerFromInstance(inst)
        if not inst then return nil end
        local cur = inst
        while cur and cur ~= workspace and cur ~= game do
            if cur:IsA("Player") then return cur end
            if cur:IsA("Model") then
                local plr = Players:GetPlayerFromCharacter(cur)
                if plr then return plr end
                local byExact = Players:FindFirstChild(cur.Name)
                if byExact and byExact:IsA("Player") then return byExact end
            end
            if cur:IsA("BillboardGui") or cur:IsA("SurfaceGui") or cur:IsA("ProximityPrompt") then
                local adornee = nil
                pcall(function() adornee = cur.Adornee end)
                if adornee then
                    local aCur = adornee
                    while aCur and aCur ~= workspace and aCur ~= game do
                        if aCur:IsA("Model") then
                            local aPlr = Players:GetPlayerFromCharacter(aCur) or Players:FindFirstChild(aCur.Name)
                            if aPlr and aPlr:IsA("Player") then return aPlr end
                        end
                        aCur = aCur.Parent
                    end
                end
            end
            cur = cur.Parent
        end
        return nil
    end

    local function findClosestPlayerWithin(originPos, maxDist, excludePlr)
        local bestP, bestD = nil, maxDist or 14
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p ~= excludePlr then
                local c = findPlayerCharacterAnywhere(p, true)
                local r = c and pickTargetRef(c, "torso")
                if r and r.Parent then
                    local d = (r.Position - originPos).Magnitude
                    if d <= bestD then
                        bestD = d
                        bestP = p
                    end
                end
            end
        end
        return bestP
    end

    local function markPlayerInteractedOrCarried(plr)
        if not plr or plr == LP or not plr.UserId then return end
        local now = tick()
        InteractedCarryPlayers[plr.UserId] = {
            triggeredAt = now,
            lastNearAt = now,
        }
    end

    local function clearPlayerInteractedOrCarried(plr)
        if not plr or not plr.UserId then return end
        InteractedCarryPlayers[plr.UserId] = nil
    end

    if ProximityPromptService then
        local function onPromptInteraction(prompt, playerWhoTriggered)
            if playerWhoTriggered and playerWhoTriggered ~= LP then return end
            if not prompt then return end
            pcall(function()
                local combinedText = tostring(prompt.ActionText or "") .. " " .. tostring(prompt.ObjectText or "") .. " " .. tostring(prompt.Name or "")
                local ownerPlr = getPlayerFromInstance(prompt)
                local myChar = LP.Character
                local myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))

                if textMatchesAny(combinedText, RELEASE_KEYWORDS) then
                    if ownerPlr and ownerPlr ~= LP then
                        clearPlayerInteractedOrCarried(ownerPlr)
                    else
                        for uid, _ in pairs(InteractedCarryPlayers) do
                            InteractedCarryPlayers[uid] = nil
                        end
                    end
                    return
                end

                if ownerPlr and ownerPlr ~= LP then
                    markPlayerInteractedOrCarried(ownerPlr)
                    return
                end

                if textMatchesAny(combinedText, CARRY_INTERACT_KEYWORDS) then
                    local promptPos = nil
                    local pParent = prompt.Parent
                    if pParent and pParent:IsA("BasePart") then
                        promptPos = pParent.Position
                    elseif pParent and pParent:IsA("Attachment") then
                        promptPos = pParent.WorldPosition
                    elseif pParent and pParent:IsA("Model") then
                        local okP, piv = pcall(function() return pParent:GetPivot() end)
                        if okP and piv then promptPos = piv.Position end
                    end
                    local refPos = promptPos or (myRoot and myRoot.Position)
                    if refPos then
                        local nearP = findClosestPlayerWithin(refPos, 14)
                        if nearP then
                            markPlayerInteractedOrCarried(nearP)
                        end
                    end
                end
            end)
        end
        pcall(function() ProximityPromptService.PromptTriggered:Connect(onPromptInteraction) end)
        pcall(function() ProximityPromptService.PromptButtonHoldEnded:Connect(onPromptInteraction) end)
    end

    local hookedGuiButtons = setmetatable({}, { __mode = "k" })
    local function inspectAndHookGuiButton(btn)
        if not btn or hookedGuiButtons[btn] then return end
        if not (btn:IsA("TextButton") or btn:IsA("ImageButton")) then return end
        local anc = btn
        while anc do
            if anc.Name:match("^Coco") then return end
            anc = anc.Parent
        end
        hookedGuiButtons[btn] = true
        pcall(function()
            btn.Activated:Connect(function()
                pcall(function()
                    local txt = ""
                    if btn:IsA("TextButton") then txt = tostring(btn.Text or "") end
                    for _, desc in ipairs(btn:GetDescendants()) do
                        if desc:IsA("TextLabel") or desc:IsA("TextButton") then
                            txt = txt .. " " .. tostring(desc.Text or "")
                        end
                    end
                    local fullStr = txt .. " " .. tostring(btn.Name or "") .. " " .. tostring(btn.Parent and btn.Parent.Name or "")
                    if textMatchesAny(fullStr, RELEASE_KEYWORDS) then
                        for uid, _ in pairs(InteractedCarryPlayers) do
                            InteractedCarryPlayers[uid] = nil
                        end
                        return
                    end
                    local adorneePlr = getPlayerFromInstance(btn)
                    if adorneePlr and adorneePlr ~= LP then
                        markPlayerInteractedOrCarried(adorneePlr)
                        return
                    end
                    if textMatchesAny(fullStr, CARRY_INTERACT_KEYWORDS) then
                        local menuRoot = btn.Parent and btn.Parent.Parent or btn.Parent
                        if menuRoot then
                            for _, d in ipairs(menuRoot:GetDescendants()) do
                                if d:IsA("TextLabel") or d:IsA("TextButton") then
                                    local dTxt = tostring(d.Text or ""):lower()
                                    if dTxt ~= "" then
                                        for _, p in ipairs(Players:GetPlayers()) do
                                            if p ~= LP and (dTxt:find(p.Name:lower(), 1, true) or (p.DisplayName ~= "" and dTxt:find(p.DisplayName:lower(), 1, true))) then
                                                markPlayerInteractedOrCarried(p)
                                                return
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        local myChar = LP.Character
                        local myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
                        if myRoot then
                            local nearP = findClosestPlayerWithin(myRoot.Position, 14)
                            if nearP then
                                markPlayerInteractedOrCarried(nearP)
                            end
                        end
                    end
                end)
            end)
        end)
    end

    pcall(function()
        local pgui = LP:FindFirstChildOfClass("PlayerGui")
        if pgui then
            pgui.DescendantAdded:Connect(function(obj)
                if obj:IsA("TextButton") or obj:IsA("ImageButton") then
                    inspectAndHookGuiButton(obj)
                end
            end)
            task.spawn(function()
                local list = pgui:GetDescendants()
                for idx, obj in ipairs(list) do
                    if obj:IsA("TextButton") or obj:IsA("ImageButton") then
                        inspectAndHookGuiButton(obj)
                    end
                    if idx % 600 == 0 then
                        RunService.Heartbeat:Wait()
                    end
                end
            end)
        end
    end)

    LP.CharacterAdded:Connect(function()
        InteractedCarryPlayers = {}
    end)

    local function valueReferencesPlayer(val, targetPlr, targetChar)
        if val == nil or not targetPlr then return false end
        local t = typeof(val)
        if t == "Instance" then
            if val == targetPlr or (targetChar and (val == targetChar or val:IsDescendantOf(targetChar))) then
                return true
            end
        elseif t == "number" then
            if val == targetPlr.UserId then return true end
        elseif t == "string" and val ~= "" then
            local low = val:lower()
            local pName = (targetPlr.Name or ""):lower()
            local pDisp = (targetPlr.DisplayName or ""):lower()
            local uidStr = tostring(targetPlr.UserId)
            if low == pName or (pDisp ~= "" and low == pDisp) or low == uidStr then
                return true
            end
            if pName ~= "" and low:find(pName, 1, true) then
                return true
            end
        end
        return false
    end

    local function hasCrossReferenceOrCarryState(sourceInst, targetPlr, targetChar, isCloseEnough)
        if not sourceInst then return false end
        local okAttr, attrs = pcall(function() return sourceInst:GetAttributes() end)
        if okAttr and attrs then
            for k, v in pairs(attrs) do
                if valueReferencesPlayer(v, targetPlr, targetChar) then
                    return true
                end
                if isCloseEnough and textMatchesAny(tostring(k), CARRY_INTERACT_KEYWORDS) then
                    if v == true or (type(v) == "number" and v ~= 0) or (type(v) == "string" and v ~= "" and v:lower() ~= "none" and v:lower() ~= "false") then
                        return true
                    end
                end
            end
        end
        -- Check direct children (and one folder level) instead of Player:GetDescendants() which would scan 5,000+ PlayerGui instances!
        for _, child in ipairs(sourceInst:GetChildren()) do
            if child:IsA("ValueBase") then
                local okV, v = pcall(function() return child.Value end)
                if okV then
                    if valueReferencesPlayer(v, targetPlr, targetChar) then
                        return true
                    end
                    if isCloseEnough and textMatchesAny(child.Name, CARRY_INTERACT_KEYWORDS) then
                        if v == true or (typeof(v) == "Instance") or (type(v) == "number" and v ~= 0) or (type(v) == "string" and v ~= "" and v:lower() ~= "none" and v:lower() ~= "false") then
                            return true
                        end
                    end
                end
            elseif child:IsA("Folder") or child:IsA("Configuration") then
                for _, sub in ipairs(child:GetChildren()) do
                    if sub:IsA("ValueBase") then
                        local okV, v = pcall(function() return sub.Value end)
                        if okV and valueReferencesPlayer(v, targetPlr, targetChar) then
                            return true
                        end
                    end
                end
            end
        end
        return false
    end

    local function isJointOrConstraintBetween(obj, charA, charB)
        if not obj or not charA or not charB then return false end
        if obj:IsA("JointInstance") or obj:IsA("WeldConstraint") then
            local p0, p1 = obj.Part0, obj.Part1
            if p0 and p1 then
                if (p0:IsDescendantOf(charA) and p1:IsDescendantOf(charB))
                    or (p1:IsDescendantOf(charA) and p0:IsDescendantOf(charB)) then
                    return true
                end
            end
        elseif obj:IsA("Constraint") then
            local a0, a1 = obj.Attachment0, obj.Attachment1
            if a0 and a1 then
                if (a0:IsDescendantOf(charA) and a1:IsDescendantOf(charB))
                    or (a1:IsDescendantOf(charA) and a0:IsDescendantOf(charB)) then
                    return true
                end
            end
        end
        return false
    end

    local CarryCheckCache = {}

    local function isPlayerCarriedOrInteracting(p, speaker)
        speaker = speaker or LP
        if not p or p == speaker or p.Parent ~= Players then return false end

        -- Never exclude a target that CocoPowder itself is actively welding/flinging/copying
        if (WeldIntent and WeldIntent.active and WeldIntent.target == p)
            or (CurrentWeld ~= nil and CurrentTarget == p)
            or (FlingActive and CurrentTarget == p)
            or (AnimCopySys and AnimCopySys.active and AnimCopySys.target == p) then
            return false
        end

        local now = os.clock()
        local cacheKey = tostring(speaker.UserId) .. "_" .. tostring(p.UserId)
        local cached = CarryCheckCache[cacheKey]
        if cached and (now - cached.t) < 0.25 then
            return cached.v
        end

        local myChar = speaker and speaker.Character
        local tChar  = findPlayerCharacterAnywhere(p, true)
        local myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
        local tRoot  = tChar and pickTargetRef(tChar, "torso")
        local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
        local tHum   = tChar and tChar:FindFirstChildOfClass("Humanoid")
        local dist   = (myRoot and tRoot) and (tRoot.Position - myRoot.Position).Magnitude or math.huge

        -- Event-driven ProximityPrompt / UI Carry & Interact tracker
        local entry = InteractedCarryPlayers[p.UserId]
        if entry then
            if tHum and tHum.Health <= 0 then
                InteractedCarryPlayers[p.UserId] = nil
            elseif dist <= 11.5 then
                entry.lastNearAt = tick()
                CarryCheckCache[cacheKey] = { t = now, v = true }
                return true
            elseif (tick() - entry.triggeredAt) <= 2.5 or (tick() - entry.lastNearAt) <= 1.2 then
                CarryCheckCache[cacheKey] = { t = now, v = true }
                return true
            else
                InteractedCarryPlayers[p.UserId] = nil
            end
        end

        -- Fast distance gate: if player is > 14 studs away and not parented to us, they cannot be physically carried!
        if dist > 14 then
            local parented = (myChar and tChar and (tChar:IsDescendantOf(myChar) or myChar:IsDescendantOf(tChar))) or false
            CarryCheckCache[cacheKey] = { t = now, v = parented }
            return parented
        end

        local result = false
        if myChar and tChar then
            if tChar:IsDescendantOf(myChar) or myChar:IsDescendantOf(tChar) then
                result = true
            elseif (tHum and tHum.SeatPart and tHum.SeatPart:IsDescendantOf(myChar))
                or (myHum and myHum.SeatPart and myHum.SeatPart:IsDescendantOf(tChar)) then
                result = true
            elseif myRoot and tRoot then
                local okAssy, sameAssy = pcall(function()
                    local a1 = myRoot.AssemblyRootPart
                    local a2 = tRoot.AssemblyRootPart
                    return (a1 ~= nil and a1 == a2)
                end)
                if okAssy and sameAssy then
                    result = true
                else
                    local okConn, connParts = pcall(function() return myRoot:GetConnectedParts(true) end)
                    if okConn and connParts then
                        for i = 1, #connParts do
                            local cp = connParts[i]
                            if cp and cp:IsDescendantOf(tChar) then
                                result = true
                                break
                            end
                        end
                    end
                end
            end

            if not result then
                for _, obj in ipairs(tChar:GetDescendants()) do
                    if isJointOrConstraintBetween(obj, myChar, tChar) then
                        result = true
                        break
                    end
                end
            end
        end

        if not result then
            local isClose = (dist <= 10.5)
            if hasCrossReferenceOrCarryState(p, speaker, myChar, isClose)
                or (tChar and hasCrossReferenceOrCarryState(tChar, speaker, myChar, isClose))
                or hasCrossReferenceOrCarryState(speaker, p, tChar, false)
                or (myChar and hasCrossReferenceOrCarryState(myChar, p, tChar, false)) then
                result = true
            end
        end

        if not result and dist <= 5.2 and myRoot and tRoot and tChar then
            if tHum then
                local okSt, tState = pcall(function() return tHum:GetState() end)
                local sitOnMe = tHum.Sit and (not tHum.SeatPart or (myChar and tHum.SeatPart:IsDescendantOf(myChar)))
                local seatedStateOnMe = okSt and (tState == Enum.HumanoidStateType.Seated) and (not tHum.SeatPart or (myChar and tHum.SeatPart:IsDescendantOf(myChar)))
                if tHum.PlatformStand
                    or sitOnMe
                    or (okSt and tState == Enum.HumanoidStateType.Physics)
                    or seatedStateOnMe
                    or tRoot.Massless then
                    result = true
                end
            end
        end

        CarryCheckCache[cacheKey] = { t = now, v = result }
        return result
    end

    OwnerAdminState.isPlayerCarriedOrInteracting = isPlayerCarriedOrInteracting

    getNearestPlayer = function(speaker)
        speaker = speaker or LP
        local myChar = speaker and speaker.Character
        local myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
        local myPos  = myRoot and myRoot.Position or Vector3.zero
        local bestPlr, bestDist = nil, math.huge

        -- 1. First pass: strictly prioritize players whose real Character BasePart is currently streamed in!
        --    (Excludes any player currently carried or interacted with by speaker!)
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= speaker and not isPlayerCarriedOrInteracting(p, speaker) then
                local c = findPlayerCharacterAnywhere(p)
                local h = c and c:FindFirstChildOfClass("Humanoid")
                local streamedCF = getVerifiedStreamedCFrame(p)
                if streamedCF and (not h or h.Health > 0) then
                    local d = (streamedCF.Position - myPos).Magnitude
                    if d < bestDist then
                        bestDist = d
                        bestPlr = p
                    end
                end
            end
        end
        if bestPlr then return bestPlr, bestDist end

        -- 2. Second pass: if no players are streamed in near us, check known/cached player positions
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= speaker and not isPlayerCarriedOrInteracting(p, speaker) then
                local c = findPlayerCharacterAnywhere(p)
                local h = c and c:FindFirstChildOfClass("Humanoid")
                local cf = getBestTargetCFrame(p)
                if cf and (not h or h.Health > 0) then
                    local d = (cf.Position - myPos).Magnitude
                    if d < bestDist then
                        bestDist = d
                        bestPlr = p
                    end
                end
            end
        end

        -- 3. Fallback: even if all players are hiding in unstreamed chunks, still return a valid server player (excluding carried/interacted)!
        if not bestPlr then
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= speaker and not isPlayerCarriedOrInteracting(p, speaker) then
                    return p, math.huge
                end
            end
        end
        return bestPlr, bestDist
    end
end

local function findPlayerByNameOrDisplay(query, speaker)
    speaker = speaker or LP
    if not query then return nil end
    local q = tostring(query):gsub("^%s*@+%s*", ""):gsub("^%s+", ""):gsub("%s+$", ""):lower()
    if q == "" then return nil end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= speaker and (p.Name:lower() == q or p.DisplayName:lower() == q) then
            return p
        end
    end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= speaker and (p.Name:lower():sub(1, #q) == q or p.DisplayName:lower():sub(1, #q) == q) then
            return p
        end
    end
    return nil
end

local WeldUsernameBoxRef = nil

local function resolveActiveTarget()
    -- 1. Check live text inside WeldUsernameBox on the Weld tab first
    if WeldUsernameBoxRef and WeldUsernameBoxRef.Parent then
        local rawBox = (WeldUsernameBoxRef.Text or ""):gsub("^%s*@+%s*", ""):gsub("^%s+", ""):gsub("%s+$", "")
        if rawBox ~= "" then
            local byBox = findPlayerByNameOrDisplay(rawBox, LP)
            if byBox and byBox.Parent == Players and byBox ~= LP then
                return byBox, false
            end
        end
    end
    -- 2. Check explicitly locked selectedPlayer from Target tab (skip if currently carried/interacted with)
    if selectedPlayer and selectedPlayer.Parent == Players and selectedPlayer ~= LP and not (OwnerAdminState.isPlayerCarriedOrInteracting and OwnerAdminState.isPlayerCarriedOrInteracting(selectedPlayer, LP)) then
        return selectedPlayer, false
    end
    -- 3. Check Chat tab target input if non-empty
    if chatTargetInput and chatTargetInput.Parent then
        local typed = (chatTargetInput.Text or ""):gsub("^%s*@+%s*", ""):gsub("^%s+", ""):gsub("%s+$", "")
        if typed ~= "" then
            local byName = findPlayerByNameOrDisplay(typed, LP)
            if byName and byName.Parent == Players then
                return byName, false
            end
        end
    end
    -- 4. Auto-Nearest Player fallback
    local nearest = getNearestPlayer(LP)
    return nearest, true
end

local function resolvePlayer(target, speaker)
    speaker = speaker or LP
    if typeof(target) == "Instance" and target:IsA("Player") then
        if target.Parent == Players and target ~= speaker then return target end
    elseif target ~= nil and tostring(target) ~= "" then
        local found = findPlayerByNameOrDisplay(target, speaker)
        if found and found.Parent == Players and found ~= speaker then return found end
    end
    local activeTgt = resolveActiveTarget()
    if activeTgt and activeTgt.Parent == Players and activeTgt ~= speaker then
        return activeTgt
    end
    return getNearestPlayer(speaker)
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 🎭 SIDE-BY-SIDE ANIMATION COPY, JERK TROLL & FULL CATALOG ANIMATION/EMOTE HUB V36.2
--    • Multi-Mode Alignment: Right (+3.2), Left (-3.2), Front Mirror (+3.2),
--      Back Shadow (+3.2), Above Float (+4.0), or In-Place Free Move (No TP)
--    • 1:1 Live AnimationTrack Mirroring + TimePosition + Speed + Dynamic Weight
--    • Intelligent Cross-Rig Motor6D Transform Mapper (R15 <-> R6 Automatic Bridge)
--    • Noclip & Massless Zero-Fling Physics Shield while locked to target
--    • Target Animate Pack Stealer with automatic Default Pack snapshot & restore
-- ═══════════════════════════════════════════════════════════════════════════════
AnimCopySys = {
    active = false,
    target = nil,
    sideMode = "right", -- "right" (+3.2), "left" (-3.2), "front" (+3.2 mirror), "back" (+3.2 shadow), "above" (+4.0), or "free" (no TP)
    sideDistance = 3.2,
    syncMotorTransforms = true, -- Default true for 0.00ms instant real-time joint + track mirroring (zero asset-download lag!)
    renderConn = nil, -- RenderStepped zero-jitter visual lock & pre-Animator track sync
    stepConn = nil,   -- Stepped phase noclip, physics lock & 1:1 Motor6D Transform bridge
    hbConn = nil,     -- Heartbeat zero-delay animation & state monitor
    descConn = nil,   -- DescendantAdded dynamic part cache (Weld engine)
    animPlayedConn = nil, -- Event-driven 0ms hook on target Animator.AnimationPlayed
    hookedAnimator = nil, -- Target Animator currently hooked
    currentLockCF = nil, -- Zero-delay locked CFrame (Weld engine)
    preCopySafeCF = nil, -- Saved safe origin CFrame before attaching
    clock = 0,           -- Internal clock for anti-sleep microWake replication
    missingFrames = 0,   -- Unstreamed target frame counter
    lastStreamReq = 0,   -- Throttled stream request timestamp
    mirroredTracks = {},   -- [source AnimationTrack] = { track, anim, animId, lastSeen, lastTimeSync, lastWeight, lastAppliedSpeed, lengthReady }
    animObjCache = {},     -- [animId] = Animation instance cache (eliminates per-track allocation & asset re-resolution delay)
    failedIds = {},         -- [animationId] = retry-after timestamp; prevents 60Hz failed-load loops
    lastNoTracksNotice = 0,
    lastLoadFailureNotice = 0,
    lastTargetAvailable = 0,
    boundCharacter = nil,
}

local EmoteHub = {
    currentEmoteTrack = nil,
    currentEmoteAnim = nil,
    currentEmoteName = nil,
    emoteSpeed = 1.0,
    emoteLooped = true,
    emoteFrozen = false,
    allowWalkDuringEmote = false,
    activePackName = "Default",
    savedDefaultPack = nil,
    packCharConn = nil,
    jerkActive = false,
    jerkSpeed = 1.6,
    jerkConn = nil,
    jerkTrack = nil,
    jerkAnim = nil,
}

do
    -- Zero-Delay Reanim Root Synchronization (Matching Weld Engine)
    local function syncAnimCopyReanimRoots(attachCF, excludePart)
        local zApi = _G._AngoorZenApi
        if zApi and type(zApi.is_reanimated) == "function" and type(zApi.get_real_character) == "function" then
            local okR, isReanim = pcall(zApi.is_reanimated)
            if okR and isReanim then
                local okC, realChar = pcall(zApi.get_real_character)
                local realRoot = okC and realChar and realChar:FindFirstChild("HumanoidRootPart")
                if realRoot and realRoot ~= excludePart and realRoot.Parent then
                    realRoot.Anchored = false
                    realRoot.CFrame = attachCF
                    realRoot.AssemblyLinearVelocity = Vector3.zero
                    realRoot.AssemblyAngularVelocity = Vector3.zero
                end
            end
        end
        local skyApi = _G.CocaSkyDestroyer
        if skyApi and type(skyApi.is_reanimated) == "function" and type(skyApi.get_real_character) == "function" then
            local okS, isSkyReanim = pcall(skyApi.is_reanimated)
            if okS and isSkyReanim then
                local okSC, skyRealChar = pcall(skyApi.get_real_character)
                local skyRealRoot = okSC and skyRealChar and skyRealChar:FindFirstChild("HumanoidRootPart")
                if skyRealRoot and skyRealRoot ~= excludePart and skyRealRoot.Parent then
                    skyRealRoot.Anchored = false
                    skyRealRoot.CFrame = attachCF
                    skyRealRoot.AssemblyLinearVelocity = Vector3.zero
                    skyRealRoot.AssemblyAngularVelocity = Vector3.zero
                end
            end
        end
    end

    -- Multi-Mode Upright Orthogonal Alignment Calculator
    -- Preserves upright pitch/roll so tilted/seated targets never teleport the player into the void or sky!
    local function computeExactSideBySideCF(tRoot, myHum, tHum, mode, dist)
        if not tRoot then return nil end
        dist = dist or 3.2
        local look = tRoot.CFrame.LookVector
        local flatLook = Vector3.new(look.X, 0, look.Z)
        if flatLook.Magnitude < 0.001 then
            flatLook = Vector3.new(0, 0, -1)
        else
            flatLook = flatLook.Unit
        end
        -- Right-hand cross product: flatLook x Y_Axis points strictly to the target's Right side
        local flatRight = flatLook:Cross(Vector3.yAxis)
        if flatRight.Magnitude < 0.001 then
            flatRight = Vector3.new(1, 0, 0)
        else
            flatRight = flatRight.Unit
        end

        local myHip = (myHum and myHum.HipHeight and myHum.HipHeight > 0.2) and myHum.HipHeight or 2.0
        local tgHip = (tHum and tHum.HipHeight and tHum.HipHeight > 0.2) and tHum.HipHeight or 2.0
        local hipDeltaY = math.clamp(myHip - tgHip, -2.5, 2.5)

        local extraX = (V and V.X) or 0
        local extraY = ((V and V.Y) or 0) + hipDeltaY
        local extraZ = ((V and V.Z) or 1.3) - 1.3

        local basePos = tRoot.Position + Vector3.new(0, extraY, 0)
        if mode == "left" then
            local worldPos = basePos - (flatRight * (dist - extraX)) - (flatLook * extraZ)
            return CFrame.fromMatrix(worldPos, flatRight, Vector3.yAxis, -flatLook)
        elseif mode == "front" then
            local worldPos = basePos + (flatLook * (dist - extraZ)) + (flatRight * extraX)
            return CFrame.fromMatrix(worldPos, -flatRight, Vector3.yAxis, flatLook)
        elseif mode == "back" then
            -- Shadow behind target facing same forward direction
            local worldPos = basePos - (flatLook * (dist + extraZ)) + (flatRight * extraX)
            return CFrame.fromMatrix(worldPos, flatRight, Vector3.yAxis, -flatLook)
        elseif mode == "above" then
            -- Majestic aerial hover directly above target
            local worldPos = basePos + Vector3.new(0, (dist or 3.8) + 1.2, 0) + (flatRight * extraX) - (flatLook * extraZ)
            return CFrame.fromMatrix(worldPos, flatRight, Vector3.yAxis, -flatLook)
        elseif mode == "orbit" then
            -- Smooth 360-degree Orbit Circle Weld facing the target while copying their animations
            local angle = os.clock() * 2.8
            local radius = math.max(1.8, (dist or 3.6) + extraX)
            local offsetVec = Vector3.new(math.cos(angle) * radius, 0, math.sin(angle) * radius)
            local worldPos = basePos + offsetVec
            local toTarget = Vector3.new(basePos.X - worldPos.X, 0, basePos.Z - worldPos.Z)
            if toTarget.Magnitude < 0.001 then toTarget = flatLook else toTarget = toTarget.Unit end
            local rightVec = toTarget:Cross(Vector3.yAxis)
            if rightVec.Magnitude < 0.001 then rightVec = Vector3.new(1, 0, 0) else rightVec = rightVec.Unit end
            return CFrame.fromMatrix(worldPos, rightVec, Vector3.yAxis, -toTarget)
        else -- "right" (default side-by-side)
            local worldPos = basePos + (flatRight * (dist + extraX)) - (flatLook * extraZ)
            return CFrame.fromMatrix(worldPos, flatRight, Vector3.yAxis, -flatLook)
        end
    end

    AnimCopySys.ComputeSideBySideCF = computeExactSideBySideCF

    local function resolveAnimCopyTarget(explicitTarget)
        if explicitTarget then
            local p = resolvePlayer(explicitTarget, LP)
            if p and p.Parent == Players and p ~= LP then return p end
        end
        if selectedPlayer and selectedPlayer.Parent == Players and selectedPlayer ~= LP and not (OwnerAdminState.isPlayerCarriedOrInteracting and OwnerAdminState.isPlayerCarriedOrInteracting(selectedPlayer, LP)) then
            return selectedPlayer
        end
        if AnimCopySys.active and AnimCopySys.target and AnimCopySys.target.Parent == Players and AnimCopySys.target ~= LP then
            return AnimCopySys.target
        end
        local res, _ = resolveActiveTarget()
        if res and res.Parent == Players and res ~= LP then
            return res
        end
        return getNearestPlayer(LP)
    end
    AnimCopySys.ResolveTarget = resolveAnimCopyTarget

    local function isBeaconTrackOrId(track, animIdStr)
        if not track then return true end
        return IsCocoBeaconTrack[track] == true
    end

    local function clearMirroredTracks(fadeTime)
        fadeTime = fadeTime == nil and 0.12 or fadeTime
        for sourceTrack, info in pairs(AnimCopySys.mirroredTracks) do
            if info.track then
                pcall(function() info.track:Stop(fadeTime) end)
                pcall(function() info.track:Destroy() end)
            end
            if info.anim then
                pcall(function() info.anim:Destroy() end)
            end
            AnimCopySys.mirroredTracks[sourceTrack] = nil
        end
    end

    function AnimCopySys:SnapSideBySideOnce(targetPlr)
        local TPlayer = resolveAnimCopyTarget(targetPlr)
        if not TPlayer or TPlayer.Parent ~= Players then
            notify("COCO POWDER", "No target player found!")
            sError()
            return false
        end
        local sideMode = self.sideMode or "right"
        local myChar = LP.Character
        local myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
        local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
        if myChar and myRoot then
            breakAllSeatsAndExternalJoints(myChar, myHum, myRoot)
        end
        -- Zero-Delay Fast Path: Snap on Frame-0 immediately if target is already streamed!
        local tChar = findPlayerCharacterAnywhere(TPlayer)
        local tRoot = tChar and pickTargetRef(tChar, "root")
        local tHum  = tChar and tChar:FindFirstChildOfClass("Humanoid")
        if tRoot and tRoot.Parent and myRoot then
            local exactCF = computeExactSideBySideCF(tRoot, myHum, tHum, sideMode, self.sideDistance or 3.2)
            if exactCF then
                markIntentionalTeleport(exactCF)
                LastKnownSafeCF = exactCF
                myRoot.Anchored = false
                myRoot.AssemblyLinearVelocity = Vector3.zero
                myRoot.AssemblyAngularVelocity = Vector3.zero
                myRoot.CFrame = exactCF
                syncAnimCopyReanimRoots(exactCF, myRoot)
                notify("🎭 SIDE-BY-SIDE", "Snapped to " .. sideMode:upper() .. " of " .. TPlayer.DisplayName .. " (0ms)!")
                sSuccess()
                return true
            end
        end
        -- Fallback async stream-piercer if target is in an unstreamed chunk
        task.spawn(function()
            local sideOffset = (sideMode == "left") and CFrame.new(-3.2, 0, 0)
                or (sideMode == "front" and (CFrame.new(0, 0, -3.2) * CFrame.Angles(0, math.pi, 0)))
                or (sideMode == "back" and CFrame.new(0, 0, 3.2))
                or (sideMode == "above" and CFrame.new(0, 4.2, 0))
                or CFrame.new(3.2, 0, 0)
            local sChar, sRoot = streamAndTeleportToTarget(TPlayer, "root", 1.8, sideOffset)
            local mChar = LP.Character
            local mRoot = mChar and (mChar:FindFirstChild("HumanoidRootPart") or mChar:FindFirstChildWhichIsA("BasePart"))
            local mHum  = mChar and mChar:FindFirstChildOfClass("Humanoid")
            local sHum  = sChar and sChar:FindFirstChildOfClass("Humanoid")
            if sRoot and sRoot.Parent and mRoot then
                local exactCF = computeExactSideBySideCF(sRoot, mHum, sHum, sideMode, self.sideDistance or 3.2)
                if exactCF then
                    markIntentionalTeleport(exactCF)
                    LastKnownSafeCF = exactCF
                    mRoot.Anchored = false
                    mRoot.AssemblyLinearVelocity = Vector3.zero
                    mRoot.AssemblyAngularVelocity = Vector3.zero
                    mRoot.CFrame = exactCF
                    syncAnimCopyReanimRoots(exactCF, mRoot)
                    notify("🎭 SIDE-BY-SIDE", "Snapped to " .. sideMode:upper() .. " of " .. TPlayer.DisplayName .. "!")
                    sSuccess()
                end
            end
        end)
        return true
    end

    function AnimCopySys:CopyTargetAnimatePack(targetPlr)
        local TPlayer = resolveAnimCopyTarget(targetPlr)
        if not TPlayer then
            notify("🎭 ANIM COPY", "No target player found to steal animation pack!")
            sError()
            return false
        end
        local tChar = findPlayerCharacterAnywhere(TPlayer)
        if not tChar then
            notify("🎭 ANIM COPY", "Target character not streamed in yet!")
            sError()
            return false
        end
        local tAnimate = tChar:FindFirstChild("Animate")
        local myChar = LP.Character
        local myAnimate = myChar and myChar:FindFirstChild("Animate")
        if not tAnimate or not myAnimate then
            notify("🎭 ANIM COPY", "Animate script not found on character!")
            sError()
            return false
        end
        if EmoteHub and EmoteHub.SaveDefaultPack then
            pcall(function() EmoteHub:SaveDefaultPack(myChar) end)
        end
        local copiedCount = 0
        for _, tVal in ipairs(tAnimate:GetChildren()) do
            local myVal = myAnimate:FindFirstChild(tVal.Name)
            if myVal then
                for _, tAnim in ipairs(tVal:GetChildren()) do
                    if tAnim:IsA("Animation") and tAnim.AnimationId ~= "" then
                        local myAnim = myVal:FindFirstChild(tAnim.Name) or myVal:FindFirstChildOfClass("Animation")
                        if myAnim and myAnim:IsA("Animation") then
                            myAnim.AnimationId = tAnim.AnimationId
                            copiedCount = copiedCount + 1
                        end
                    end
                end
            end
        end
        local myHum = myChar:FindFirstChildOfClass("Humanoid")
        if myHum then
            stopDefaultTracks(myChar)
            pcall(function() myHum:ChangeState(Enum.HumanoidStateType.Landed) end)
        end
        notify("🎭 PACK COPIED", "Copied " .. tostring(copiedCount) .. " Animation Pack tracks from " .. TPlayer.DisplayName .. "!")
        sSuccess()
        return true
    end

    function AnimCopySys:Stop(skipSafeReturn)
        if not self.active and not self.hbConn and not self.stepConn and not self.renderConn then return end
        self.active = false
        self.target = nil
        self.currentLockCF = nil
        if WeldIntent.presetKey == "animcopy" then
            WeldIntent.active = false
            WeldIntent.presetKey = nil
            WeldIntent.target = nil
        end
        if self.animPlayedConn then pcall(function() self.animPlayedConn:Disconnect() end); self.animPlayedConn = nil end
        self.hookedAnimator = nil
        if self.renderConn then self.renderConn:Disconnect(); self.renderConn = nil end
        if self.stepConn then self.stepConn:Disconnect(); self.stepConn = nil end
        if self.hbConn then self.hbConn:Disconnect(); self.hbConn = nil end
        if self.descConn then self.descConn:Disconnect(); self.descConn = nil end
        clearMirroredTracks(0)
        self.lastTargetAvailable = 0
        self.boundCharacter = nil
        pcall(function() LP.ReplicationFocus = nil end)

        local myChar = LP.Character
        local myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
        local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
        if myRoot and sethiddenproperty then
            pcall(function() sethiddenproperty(myRoot, "PhysicsRepRootPart", nil) end)
            pcall(function() sethiddenproperty(myRoot, "PhysicsRepRootRef", nil) end)
        end
        if myChar then
            local keepNoclip = (moveState and moveState.noclip) == true
            local keepNoTouch = (Anti and Anti.Kill and Anti.Kill.enabled) == true
            for _, d in ipairs(myChar:GetDescendants()) do
                if d:IsA("BasePart") then
                    d.Massless = false
                    d.CanQuery = true
                    d.CanTouch = not keepNoTouch
                    if d.Name == "HumanoidRootPart" or d.Name == "Torso" or d.Name == "UpperTorso" or d.Name == "LowerTorso" or d.Name == "Head" then
                        d.CanCollide = not keepNoclip
                    end
                elseif d:IsA("Motor6D") then
                    pcall(function() d.Transform = CFrame.identity end)
                end
            end
            restoreAnimate(myChar)
        end
        if myHum and myHum.Health > 0 then
            pcall(function()
                myHum.PlatformStand = false
                myHum.Sit = false
                myHum.AutoRotate = true
                myHum:ChangeState(Enum.HumanoidStateType.GettingUp)
                myHum:ChangeState(Enum.HumanoidStateType.Running)
            end)
        end
        if not skipSafeReturn and myChar and myRoot then
            if isSafePlayableCF(myRoot.CFrame) then
                local cleanCF = getFlatYawCFrame(myRoot.CFrame)
                markIntentionalTeleport(cleanCF)
                LastKnownSafeCF = cleanCF
                myRoot.AssemblyLinearVelocity = Vector3.zero
                myRoot.AssemblyAngularVelocity = Vector3.zero
                myRoot.CFrame = cleanCF
            else
                LastVoidActionEnd = tick()
                safeReturnFromVoid(myChar, self.preCopySafeCF or LastKnownSafeCF)
            end
        end
        if not (Anti and Anti.Void and Anti.Void.enabled) and not (Anti and Anti.Kill and Anti.Kill.enabled) and not WeldIntent.active and not FlingActive then
            pcall(function() workspace.FallenPartsDestroyHeight = OriginalFPDH end)
        end
        if syncAllActiveIndicators then pcall(syncAllActiveIndicators) end
    end

    local MotorPairCache = setmetatable({}, { __mode = "k" })
    -- Cross-Rig Motor6D Joint Mapper: Bridges R15 <-> R6 procedural poses with cached Motor6D pairs (zero GetDescendants lag)
    local function applyCrossRigMotorTransforms(myChar, tChar, myRig, tRig)
        if not myChar or not tChar then return end
        if myRig == tRig then
            local cache = MotorPairCache[tChar]
            if not cache or cache.myChar ~= myChar or (os.clock() - cache.builtAt) > 1.5 then
                local pairsList = {}
                for _, tMotor in ipairs(tChar:GetDescendants()) do
                    if tMotor:IsA("Motor6D") and tMotor.Parent then
                        local myPart = myChar:FindFirstChild(tMotor.Parent.Name)
                        local myMotor = myPart and myPart:FindFirstChild(tMotor.Name)
                        if myMotor and myMotor:IsA("Motor6D") then
                            pairsList[#pairsList + 1] = { src = tMotor, dst = myMotor }
                        end
                    end
                end
                cache = { myChar = myChar, builtAt = os.clock(), pairs = pairsList }
                MotorPairCache[tChar] = cache
            end
            for i = 1, #cache.pairs do
                local pair = cache.pairs[i]
                if pair.src.Parent and pair.dst.Parent then
                    pair.dst.Transform = pair.src.Transform
                end
            end
        elseif myRig == Enum.HumanoidRigType.R15 and tRig == Enum.HumanoidRigType.R6 then
            local tTorso = tChar:FindFirstChild("Torso")
            if not tTorso then return end
            local tNeck = tTorso:FindFirstChild("Neck")
            local tRSh  = tTorso:FindFirstChild("Right Shoulder")
            local tLSh  = tTorso:FindFirstChild("Left Shoulder")
            local tRHip = tTorso:FindFirstChild("Right Hip")
            local tLHip = tTorso:FindFirstChild("Left Hip")
            local tRootJ = (tChar:FindFirstChild("HumanoidRootPart") and tChar.HumanoidRootPart:FindFirstChild("RootJoint")) or tTorso:FindFirstChild("RootJoint")

            local head = myChar:FindFirstChild("Head")
            local lTorso = myChar:FindFirstChild("LowerTorso")
            local rUArm = myChar:FindFirstChild("RightUpperArm")
            local lUArm = myChar:FindFirstChild("LeftUpperArm")
            local rULeg = myChar:FindFirstChild("RightUpperLeg")
            local lULeg = myChar:FindFirstChild("LeftUpperLeg")

            if tNeck and head and head:FindFirstChild("Neck") then
                pcall(function() head.Neck.Transform = tNeck.Transform end)
            end
            if tRootJ and lTorso and lTorso:FindFirstChild("Root") then
                pcall(function() lTorso.Root.Transform = tRootJ.Transform end)
            end
            if tRSh and rUArm and rUArm:FindFirstChild("RightShoulder") then
                pcall(function() rUArm.RightShoulder.Transform = tRSh.Transform end)
            end
            if tLSh and lUArm and lUArm:FindFirstChild("LeftShoulder") then
                pcall(function() lUArm.LeftShoulder.Transform = tLSh.Transform end)
            end
            if tRHip and rULeg and rULeg:FindFirstChild("RightHip") then
                pcall(function() rULeg.RightHip.Transform = tRHip.Transform end)
            end
            if tLHip and lULeg and lULeg:FindFirstChild("LeftHip") then
                pcall(function() lULeg.LeftHip.Transform = tLHip.Transform end)
            end
        elseif myRig == Enum.HumanoidRigType.R6 and tRig == Enum.HumanoidRigType.R15 then
            local myTorso = myChar:FindFirstChild("Torso")
            if not myTorso then return end
            local head = tChar:FindFirstChild("Head")
            local uTorso = tChar:FindFirstChild("UpperTorso")
            local lTorso = tChar:FindFirstChild("LowerTorso")
            local rUArm = tChar:FindFirstChild("RightUpperArm")
            local rLArm = tChar:FindFirstChild("RightLowerArm")
            local lUArm = tChar:FindFirstChild("LeftUpperArm")
            local lLArm = tChar:FindFirstChild("LeftLowerArm")
            local rULeg = tChar:FindFirstChild("RightUpperLeg")
            local rLLeg = tChar:FindFirstChild("RightLowerLeg")
            local lULeg = tChar:FindFirstChild("LeftUpperLeg")
            local lLLeg = tChar:FindFirstChild("LeftLowerLeg")

            if head and head:FindFirstChild("Neck") and myTorso:FindFirstChild("Neck") then
                pcall(function() myTorso.Neck.Transform = head.Neck.Transform end)
            end
            local myRootJ = (myChar:FindFirstChild("HumanoidRootPart") and myChar.HumanoidRootPart:FindFirstChild("RootJoint")) or myTorso:FindFirstChild("RootJoint")
            if lTorso and lTorso:FindFirstChild("Root") and myRootJ then
                local wTf = (uTorso and uTorso:FindFirstChild("Waist") and uTorso.Waist.Transform) or CFrame.identity
                pcall(function() myRootJ.Transform = lTorso.Root.Transform * wTf end)
            end
            if rUArm and rUArm:FindFirstChild("RightShoulder") and myTorso:FindFirstChild("Right Shoulder") then
                local elb = (rLArm and rLArm:FindFirstChild("RightElbow") and rLArm.RightElbow.Transform) or CFrame.identity
                pcall(function() myTorso["Right Shoulder"].Transform = rUArm.RightShoulder.Transform * elb end)
            end
            if lUArm and lUArm:FindFirstChild("LeftShoulder") and myTorso:FindFirstChild("Left Shoulder") then
                local elb = (lLArm and lLArm:FindFirstChild("LeftElbow") and lLArm.LeftElbow.Transform) or CFrame.identity
                pcall(function() myTorso["Left Shoulder"].Transform = lUArm.LeftShoulder.Transform * elb end)
            end
            if rULeg and rULeg:FindFirstChild("RightHip") and myTorso:FindFirstChild("Right Hip") then
                local kn = (rLLeg and rLLeg:FindFirstChild("RightKnee") and rLLeg.RightKnee.Transform) or CFrame.identity
                pcall(function() myTorso["Right Hip"].Transform = rULeg.RightHip.Transform * kn end)
            end
            if lULeg and lULeg:FindFirstChild("LeftHip") and myTorso:FindFirstChild("Left Hip") then
                local kn = (lLLeg and lLLeg:FindFirstChild("LeftKnee") and lLLeg.LeftKnee.Transform) or CFrame.identity
                pcall(function() myTorso["Left Hip"].Transform = lULeg.LeftHip.Transform * kn end)
            end
        end
    end

    -- Instant Zero-Latency Track Synchronizer: Called on Frame-0, RenderStepped (Pre-Animator), AnimationPlayed Event & Heartbeat
    local function syncTargetAnimationTracksNow(self, c, hum, tc, th)
        if not self.active or not c or not hum or not tc or not th then return false end
        local tAnimator = th:FindFirstChildOfClass("Animator") or tc:FindFirstChildWhichIsA("Animator", true)
        local myAnimator = hum:FindFirstChildOfClass("Animator")
        if not myAnimator then
            pcall(function() myAnimator = Instance.new("Animator"); myAnimator.Parent = hum end)
        end
        if not myAnimator then return false end

        -- Hook target Animator.AnimationPlayed so any newly started animation mirrors at 0.00ms on the exact event tick
        if tAnimator and self.hookedAnimator ~= tAnimator then
            if self.animPlayedConn then pcall(function() self.animPlayedConn:Disconnect() end); self.animPlayedConn = nil end
            self.hookedAnimator = tAnimator
            pcall(function()
                self.animPlayedConn = tAnimator.AnimationPlayed:Connect(function()
                    if not self.active then return end
                    local curC = LP.Character
                    local curH = curC and curC:FindFirstChildOfClass("Humanoid")
                    local curTC = self.target and findPlayerCharacterAnywhere(self.target)
                    local curTH = curTC and curTC:FindFirstChildOfClass("Humanoid")
                    if curC and curH and curTC and curTH then
                        syncTargetAnimationTracksNow(self, curC, curH, curTC, curTH)
                    end
                end)
            end)
        end

        local okTracks, tTracks = false, nil
        if tAnimator then
            okTracks, tTracks = pcall(function() return tAnimator:GetPlayingAnimationTracks() end)
        end

        local now = os.clock()
        local speedMult = math.clamp((V and V.Speed) or 1.0, 0.2, 6.0)

        if not okTracks or not tTracks or #tTracks == 0 then
            for sourceTrack, entry in pairs(self.mirroredTracks) do
                pcall(function() if entry.track then entry.track:Stop(0); entry.track:Destroy() end end)
                self.mirroredTracks[sourceTrack] = nil
            end
            return true -- Signal caller to bridge via Motor6D Transform matrix
        end

        local seenTracks = {}
        local anyTrackStillLoading = false

        for i = 1, #tTracks do
            local trTrack = tTracks[i]
            local sourceWeight = trTrack.WeightCurrent or 1
            if trTrack.IsPlaying and sourceWeight > 0.0005 then
                local animObj = trTrack.Animation
                local rawAnimId = animObj and tostring(animObj.AnimationId or "") or ""
                local animId = rawAnimId
                if animId:match("^%d+$") then
                    animId = "rbxassetid://" .. animId
                end

                if animId ~= "" and not isBeaconTrackOrId(trTrack, animId)
                    and not (self.failedIds[animId] and self.failedIds[animId] > tick()) then
                    seenTracks[trTrack] = true
                    local entry = self.mirroredTracks[trTrack]
                    if not entry or not entry.track or not entry.track.IsPlaying or entry.animId ~= animId then
                        if entry and entry.track then
                            pcall(function() entry.track:Stop(0); entry.track:Destroy() end)
                        end
                        entry = nil
                        pcall(function()
                            local cachedAnim = self.animObjCache[animId]
                            if not cachedAnim or cachedAnim.AnimationId ~= animId then
                                cachedAnim = Instance.new("Animation")
                                cachedAnim.AnimationId = animId
                                self.animObjCache[animId] = cachedAnim
                            end
                            local loaded = myAnimator:LoadAnimation(cachedAnim)
                            loaded.Priority = trTrack.Priority
                            loaded.Looped = trTrack.Looped
                            local sourceSpeed = trTrack.Speed or 1
                            local sourceTime = trTrack.TimePosition or 0
                            local clampedW = math.clamp(sourceWeight, 0.01, 1)
                            -- ZERO-DELAY INSTANT PLAY (0.00s fade time)
                            loaded:Play(0, clampedW, sourceSpeed * speedMult)
                            loaded:AdjustWeight(clampedW, 0)
                            local lenReady = (loaded.Length and loaded.Length > 0) or false
                            if lenReady then
                                loaded.TimePosition = math.max(0, sourceTime)
                            else
                                anyTrackStillLoading = true
                            end
                            entry = {
                                track = loaded,
                                anim = cachedAnim,
                                animId = animId,
                                lastSeen = now,
                                lastTimeSync = now,
                                lastWeight = clampedW,
                                lastAppliedSpeed = sourceSpeed * speedMult,
                                lengthReady = lenReady,
                            }
                            self.mirroredTracks[trTrack] = entry
                            self.failedIds[animId] = nil
                        end)
                        if not entry then
                            self.failedIds[animId] = tick() + 8
                            anyTrackStillLoading = true
                        end
                    end

                    if entry and entry.track then
                        local sourceSpeed = trTrack.Speed or 1
                        local sourceTime = trTrack.TimePosition or 0
                        entry.track.Looped = trTrack.Looped
                        entry.track.Priority = trTrack.Priority
                        entry.lastSeen = now

                        local desiredSpeed = sourceSpeed * speedMult
                        if not entry.lastAppliedSpeed or math.abs(entry.lastAppliedSpeed - desiredSpeed) > 0.01 then
                            entry.track:AdjustSpeed(desiredSpeed)
                            entry.lastAppliedSpeed = desiredSpeed
                        end

                        local desiredWeight = math.clamp(sourceWeight, 0.01, 1)
                        if not entry.lastWeight or math.abs(entry.lastWeight - desiredWeight) > 0.015 then
                            entry.track:AdjustWeight(desiredWeight, 0)
                            entry.lastWeight = desiredWeight
                        end

                        local trackLen = entry.track.Length or 0
                        if trackLen > 0 then
                            -- If asset just finished downloading this frame, snap TimePosition immediately!
                            if not entry.lengthReady then
                                entry.lengthReady = true
                                entry.track.TimePosition = math.clamp(sourceTime, 0, trackLen)
                            else
                                local diff = math.abs(entry.track.TimePosition - sourceTime)
                                if entry.track.Looped and trackLen > 0.1 then
                                    diff = math.min(diff, math.abs(trackLen - diff))
                                end
                                -- Tight 15ms real-time frame lock so animations never drift or lag behind
                                if diff > 0.015 then
                                    entry.track.TimePosition = math.clamp(sourceTime, 0, trackLen)
                                end
                            end
                        else
                            anyTrackStillLoading = true
                        end
                    end
                end
            end
        end

        -- ZERO-DELAY STOP: Immediately stop any track on the exact frame the target stops or switches it (no 0.25s/0.40s lag!)
        for sourceTrack, entry in pairs(self.mirroredTracks) do
            if not seenTracks[sourceTrack] then
                pcall(function() if entry.track then entry.track:Stop(0); entry.track:Destroy() end end)
                self.mirroredTracks[sourceTrack] = nil
            end
        end

        return anyTrackStillLoading
    end

    function AnimCopySys:Start(targetPlr)
        if OwnerAdminState.isFrozenByOwner or OwnerAdminState.isBannedByOwner then
            notify("👑 ADMIN LOCK", "You are currently frozen/locked by an Admin!")
            sError()
            return false
        end
        local TPlayer = resolveAnimCopyTarget(targetPlr)
        if not TPlayer or TPlayer.Parent ~= Players then
            notify("COCO POWDER", "No target player found to copy animations!")
            sError()
            return false
        end
        if isProtectedFromLocalPlayer(TPlayer) then
            notify("👑 IMMUNITY", "Cannot target the Coco Powder Script Owner!")
            sError()
            return false
        end

        local myChar = LP.Character
        local myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
        local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
        if not myChar or not myRoot or not myHum or myHum.Health <= 0 then
            notify("COCO POWDER", "Character not ready to copy animations!")
            sError()
            return false
        end

        if CurrentWeld then pcall(function() CurrentWeld:Destroy(true) end); CurrentWeld = nil end
        if EmoteHub and EmoteHub.StopEmote then pcall(function() EmoteHub:StopEmote() end) end
        if EmoteHub and EmoteHub.StopJerk then pcall(function() EmoteHub:StopJerk() end) end
        self:Stop(true)

        -- Capture safe origin CFrame and disable FallenPartsDestroyHeight (exact Weld engine protection)
        pcall(function() workspace.FallenPartsDestroyHeight = 0/0 end)
        self.preCopySafeCF = isSafePlayableCF(myRoot.CFrame) and myRoot.CFrame or LastKnownSafeCF or findFallbackSafeCF()

        clearMirroredTracks(0)
        self.failedIds = {}
        self.lastTargetAvailable = os.clock()
        self.boundCharacter = myChar
        self.clock = 0
        self.missingFrames = 0
        self.lastStreamReq = 0
        self.active = true
        self.target = TPlayer
        CurrentTarget = TPlayer
        WeldIntent.active = true
        WeldIntent.presetKey = "animcopy"
        WeldIntent.target = TPlayer
        WeldIntent.waitingForSpawn = false
        WeldIntent.leftInfo = nil
        WeldIntent.topStatusText = "active · Copy Animation (Side-by-Side)"
        WeldIntent.topStatusColor = T.Success
        WeldIntent.midStatusText = "attached · " .. TPlayer.Name
        WeldIntent.midStatusColor = T.Success
        WeldIntent.bottomStatusText = "target online · attached (Copy Animation)"
        WeldIntent.bottomStatusColor = T.Success
        LastPresetKey = "animcopy"
        LastWeldTargetUserId = TPlayer.UserId
        hookTargetRespawn(TPlayer)
        if WeldIntent.refreshUI then pcall(WeldIntent.refreshUI) end
        if syncAllActiveIndicators then pcall(syncAllActiveIndicators) end

        -- ═══════════════════════════════════════════════════════════════════
        -- ⚡ ZERO-DELAY WELD PIPELINE FOR ANIMATION COPY (0.00ms FRAME-0 LOCK)
        -- ═══════════════════════════════════════════════════════════════════
        -- 1. Sever any external SeatWeld / VehicleSeat weld & kill default Animate script immediately
        breakAllSeatsAndExternalJoints(myChar, myHum, myRoot)
        killAnimate(myChar)

        -- 2. Phase noclip part cache setup (matching WeldTo)
        local copyCachedParts = {}
        for _, part in ipairs(myChar:GetDescendants()) do
            if part:IsA("BasePart") then
                copyCachedParts[#copyCachedParts + 1] = part
                part.CanCollide = false
                part.CanTouch = false
                part.CanQuery = false
                part.Massless = true
                part.Anchored = false
            elseif part:IsA("SeatWeld") or part.Name == "SeatWeld" then
                pcall(function() part:Destroy() end)
            end
        end

        self.descConn = myChar.DescendantAdded:Connect(function(v)
            if not self.active then return end
            if v:IsA("BasePart") then
                copyCachedParts[#copyCachedParts + 1] = v
                v.CanCollide = false
                v.CanTouch = false
                v.CanQuery = false
                v.Massless = true
                v.Anchored = false
            elseif v:IsA("Tool") then
                for _, tp in ipairs(v:GetDescendants()) do
                    if tp:IsA("BasePart") then
                        copyCachedParts[#copyCachedParts + 1] = tp
                        tp.CanCollide = false
                        tp.CanTouch = false
                        tp.CanQuery = false
                        tp.Massless = true
                        tp.Anchored = false
                    end
                end
            elseif v:IsA("SeatWeld") or v.Name == "SeatWeld" then
                pcall(function() v:Destroy() end)
            end
        end)

        local function applyCopyPhaseNoclip()
            for i = 1, #copyCachedParts do
                local v = copyCachedParts[i]
                if v and v.Parent then
                    if v.CanCollide then v.CanCollide = false end
                    if v.CanTouch then v.CanTouch = false end
                    if v.CanQuery then v.CanQuery = false end
                    if not v.Massless then v.Massless = true end
                    if v.Anchored then v.Anchored = false end
                end
            end
            if myHum and myHum.Sit then
                pcall(function() myHum.Sit = false end)
            end
        end
        applyCopyPhaseNoclip()

        -- 3. Immediate Frame-0 CFrame Lock (0.00ms startup delay!)
        local tChar = findPlayerCharacterAnywhere(TPlayer)
        local tRoot = tChar and pickTargetRef(tChar, "root")
        local tHum  = tChar and tChar:FindFirstChildOfClass("Humanoid")
        if self.sideMode ~= "free" then
            if tRoot and tRoot.Parent then
                local initialCF = computeExactSideBySideCF(tRoot, myHum, tHum, self.sideMode, self.sideDistance or 3.2)
                if initialCF then
                    self.currentLockCF = initialCF
                    markIntentionalTeleport(initialCF)
                    LastKnownSafeCF = initialCF
                    myRoot.Anchored = false
                    myRoot.CFrame = initialCF
                    myRoot.AssemblyLinearVelocity = tRoot.AssemblyLinearVelocity
                    myRoot.AssemblyAngularVelocity = Vector3.zero
                    syncAnimCopyReanimRoots(initialCF, myRoot)
                end
            else
                -- Target is in an unstreamed chunk; kick off non-blocking stream piercer
                task.spawn(function()
                    local sideOffset = (self.sideMode == "left") and CFrame.new(-3.2, 0, 0)
                        or (self.sideMode == "front" and (CFrame.new(0, 0, -3.2) * CFrame.Angles(0, math.pi, 0)))
                        or (self.sideMode == "back" and CFrame.new(0, 0, 3.2))
                        or (self.sideMode == "above" and CFrame.new(0, 4.2, 0))
                        or CFrame.new(3.2, 0, 0)
                    streamAndTeleportToTarget(TPlayer, "root", 1.8, sideOffset)
                end)
            end
        end

        -- Sync target animations immediately on Frame-0 so there is 0.00ms startup latency!
        if tChar and tHum then
            pcall(function()
                local needBridge = syncTargetAnimationTracksNow(self, myChar, myHum, tChar, tHum)
                if self.syncMotorTransforms or needBridge or myHum.RigType ~= tHum.RigType then
                    applyCrossRigMotorTransforms(myChar, tChar, myHum.RigType, tHum.RigType)
                end
            end)
        end

        -- 4. Pass 1: RenderStepped Zero-Delay Visual Lock & Pre-Animator Track Sync
        self.renderConn = RunService.RenderStepped:Connect(function()
            if not self.active then return end
            local c = LP.Character
            local root = c and (c:FindFirstChild("HumanoidRootPart") or c:FindFirstChildWhichIsA("BasePart"))
            local hum = c and c:FindFirstChildOfClass("Humanoid")
            if not c or not root or not hum then return end

            local tc = self.target and findPlayerCharacterAnywhere(self.target)
            local tr = tc and pickTargetRef(tc, "root")
            local th = tc and tc:FindFirstChildOfClass("Humanoid")
            if not tc or not tr or not tr.Parent or not th or th.Health <= 0 then return end

            if self.sideMode ~= "free" and not isLethalVoidCF(tr.CFrame, tr.AssemblyLinearVelocity) then
                local desiredCF = computeExactSideBySideCF(tr, hum, th, self.sideMode, self.sideDistance or 3.2)
                if desiredCF then
                    self.currentLockCF = desiredCF
                    root.CFrame = desiredCF
                    syncAnimCopyReanimRoots(desiredCF, root)
                end
            end
            -- Sync AnimationTracks BEFORE Roblox's internal Animator step so new animations & TimePositions apply on the current frame!
            syncTargetAnimationTracksNow(self, c, hum, tc, th)
        end)

        -- 5. Pass 2: Stepped Phase Noclip, Physics Lock & Real-Time Motor6D Pose Bridge
        self.stepConn = RunService.Stepped:Connect(function()
            if not self.active then return end
            applyCopyPhaseNoclip()
            local c = LP.Character
            local root = c and (c:FindFirstChild("HumanoidRootPart") or c:FindFirstChildWhichIsA("BasePart"))
            if self.sideMode ~= "free" and self.currentLockCF and root and root.Parent then
                root.CFrame = self.currentLockCF
                syncAnimCopyReanimRoots(self.currentLockCF, root)
            end
            local tc = self.target and findPlayerCharacterAnywhere(self.target)
            local th = tc and tc:FindFirstChildOfClass("Humanoid")
            local myH = c and c:FindFirstChildOfClass("Humanoid")
            if tc and th and myH then
                -- Always bridge Motor6D.Transform when enabled, cross-rig, or while any new animation asset is still downloading
                if self.syncMotorTransforms or myH.RigType ~= th.RigType then
                    applyCrossRigMotorTransforms(c, tc, myH.RigType, th.RigType)
                else
                    for _, entry in pairs(self.mirroredTracks) do
                        if not entry.lengthReady then
                            applyCrossRigMotorTransforms(c, tc, myH.RigType, th.RigType)
                            break
                        end
                    end
                end
            end
        end)

        -- 6. Pass 3: Heartbeat Omnipresent Lock, Physics Replication & Zero-Delay Animation Sync
        self.hbConn = RunService.Heartbeat:Connect(function(dt)
            if not self.active then return end
            local c = LP.Character
            local root = c and (c:FindFirstChild("HumanoidRootPart") or c:FindFirstChildWhichIsA("BasePart"))
            local hum  = c and c:FindFirstChildOfClass("Humanoid")
            if not c or not root or not hum or hum.Health <= 0 then
                local savedTgt = self.target
                self:Stop(true)
                if AutoReweldEnabled and savedTgt and savedTgt.Parent == Players then
                    WeldIntent.active = true
                    WeldIntent.presetKey = "animcopy"
                    WeldIntent.target = savedTgt
                end
                return
            end

            if not self.target or self.target.Parent ~= Players then
                local leftPlr = self.target
                local lName = leftPlr and leftPlr.Name or tostring(WeldIntent.typedUsername or "Target")
                local lDisp = (leftPlr and leftPlr.DisplayName) or lName
                local lUid  = leftPlr and leftPlr.UserId or LastWeldTargetUserId
                self:Stop(false)
                WeldIntent.leftInfo = {
                    userId = lUid,
                    name = lName,
                    displayName = lDisp,
                    accountAge = "—",
                    friendsText = "—",
                    leftAt = tick(),
                    wasWelded = true,
                    presetKey = "animcopy",
                }
                WeldIntent.presetKey = "animcopy"
                LastPresetKey = "animcopy"
                WeldIntent.typedUsername = lName
                WeldIntent.waitingForSpawn = true
                WeldIntent.topStatusText = "target left · weld stopped"
                WeldIntent.topStatusColor = T.Danger
                WeldIntent.midStatusText = "target left · " .. lName
                WeldIntent.midStatusColor = T.Danger
                WeldIntent.bottomStatusText = "target offline · will attach on spawn"
                WeldIntent.bottomStatusColor = T.Warning
                if WeldIntent.refreshUI then pcall(WeldIntent.refreshUI) end
                showOwnerScreenBanner(
                    "🚨 TARGET HAS LEFT THE GAME",
                    "@" .. lName .. " (" .. lDisp .. ") left — weld stopped · will attach on spawn",
                    T.Danger,
                    4.5,
                    "TargetLeftBanner"
                )
                notify("COCO POWDER", "Target has left the game: @" .. lName .. " (weld stopped)")
                return
            end

            local now = os.clock()
            if self.boundCharacter ~= c then
                clearMirroredTracks(0)
                self.boundCharacter = c
                breakAllSeatsAndExternalJoints(c, hum, root)
                killAnimate(c)
            end

            local tc = findPlayerCharacterAnywhere(self.target)
            local tr = tc and pickTargetRef(tc, "root")
            local th = tc and tc:FindFirstChildOfClass("Humanoid")

            -- Omnipresent Re-Lock & Unstreamed Hiding-Spot Follow (exact WeldTo logic)
            if not tr or not tr.Parent or not th or th.Health <= 0 then
                if th and th.Health <= 0 then
                    WeldIntent.waitingForSpawn = true
                    WeldIntent.topStatusText = "target respawning · waiting"
                    WeldIntent.topStatusColor = T.Warning
                    WeldIntent.midStatusText = "respawning · " .. self.target.Name
                    WeldIntent.midStatusColor = T.Warning
                    WeldIntent.bottomStatusText = "target respawning · will attach on spawn"
                    WeldIntent.bottomStatusColor = T.Warning
                    if WeldIntent.refreshUI then pcall(WeldIntent.refreshUI) end
                elseif self.sideMode ~= "free" then
                    self.missingFrames = (self.missingFrames or 0) + 1
                    local hiddenCF = getBestTargetCFrame(self.target) or getTargetStreamHintCFrame(self.target)
                    if hiddenCF and not isLethalVoidCF(hiddenCF) then
                        local tNow = tick()
                        if tNow - (self.lastStreamReq or 0) > 0.35 then
                            self.lastStreamReq = tNow
                            ensureStreamFocusAt(hiddenCF)
                            task.spawn(function()
                                pcall(function() LP:RequestStreamAroundAsync(hiddenCF.Position, 1.5) end)
                            end)
                        end
                        local chaseCF = hiddenCF * CFrame.new(self.sideDistance or 3.2, 0, 0)
                        self.currentLockCF = chaseCF
                        root.CFrame = chaseCF
                        root.AssemblyLinearVelocity = Vector3.zero
                        root.AssemblyAngularVelocity = Vector3.zero
                        markIntentionalTeleport(chaseCF)
                    end
                end
                if self.lastTargetAvailable > 0 and now - self.lastTargetAvailable > 1.25 then
                    clearMirroredTracks(0.18)
                end
                return
            end
            self.missingFrames = 0
            self.lastTargetAvailable = now

            -- Void Protection: Detach safely if target plummets into lethal void killzone
            local tVel = tr.AssemblyLinearVelocity
            if self.sideMode ~= "free" and isLethalVoidCF(tr.CFrame, tVel) then
                self:Stop(false)
                notify("COCO POWDER", "Target fell into lethal Void — detached safely!")
                return
            end

            -- Keep server streaming focused on the target's root part
            local focusPart = (tc and (tc:FindFirstChild("HumanoidRootPart") or tr)) or tr
            pcall(function() LP.ReplicationFocus = focusPart end)

            -- Cache target location & update safe standing CFrame
            PlayerLocationCache[self.target.UserId] = { cf = tr.CFrame, time = tick(), verified = true }
            if WeldIntent.waitingForSpawn then
                WeldIntent.waitingForSpawn = false
                if WeldIntent.refreshUI then pcall(WeldIntent.refreshUI) end
            end
            if not isLethalVoidCF(tr.CFrame, tVel) and math.abs(tVel.Y) < 45 and (not th or th.FloorMaterial ~= Enum.Material.Air) then
                local _, yYaw, _ = tr.CFrame:ToEulerAnglesYXZ()
                self.preCopySafeCF = CFrame.new(tr.Position + Vector3.new(0, 2.5, 0)) * CFrame.Angles(0, yYaw, 0)
                LastKnownSafeCF = self.preCopySafeCF
            end

            local animate = c:FindFirstChild("Animate")
            if animate and not animate.Disabled then
                animate.Disabled = true
                AnimateWasDisabled = true
            end

            local speedMult = math.clamp((V and V.Speed) or 1.0, 0.2, 6.0)
            self.clock = (self.clock or 0) + (dt * speedMult)

            if self.sideMode ~= "free" then
                local desiredCF = computeExactSideBySideCF(tr, hum, th, self.sideMode, self.sideDistance or 3.2)
                if desiredCF then
                    self.currentLockCF = desiredCF
                    root.Anchored = false
                    root.CFrame = desiredCF
                    syncAnimCopyReanimRoots(desiredCF, root)
                    -- Velocity-matched anti-sleep replication (from WeldTo): prevents network sleep & trailing lag on other players' screens
                    local microWake = Vector3.new(0, math.sin(self.clock * 24) * 0.03, 0)
                    root.AssemblyLinearVelocity = (tVel.Magnitude < 350 and (tVel * 0.85) or Vector3.zero) + microWake
                    root.AssemblyAngularVelocity = Vector3.zero
                    markIntentionalTeleport(desiredCF)
                    if sethiddenproperty then
                        pcall(function()
                            sethiddenproperty(root, "PhysicsRepRootPart", focusPart)
                            if InstanceHandleNew then
                                sethiddenproperty(root, "PhysicsRepRootRef", InstanceHandleNew(focusPart))
                            end
                            sethiddenproperty(root, "NetworkIsSleeping", false)
                        end)
                    end
                    pcall(function()
                        if hum.Sit then hum.Sit = false end
                        hum.AutoRotate = false
                    end)
                end
            else
                pcall(function() hum.AutoRotate = true end)
            end

            local needBridge = syncTargetAnimationTracksNow(self, c, hum, tc, th)
            if needBridge or self.syncMotorTransforms or hum.RigType ~= th.RigType then
                applyCrossRigMotorTransforms(c, tc, hum.RigType, th.RigType)
            end
        end)

        return true, TPlayer
    end

