    if syncAllActiveIndicators then pcall(syncAllActiveIndicators) end
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Troll Redirect ON (transfers attackers to another player)")
    sToggleOn()
end
