                    float   = { 121210361161914, 180436148, 180435571 },
                    soar    = { 99148979036185, 180436148, 125750702 },
                    land    = { 121210361161914, 180436148, 180435571 },
                },
            },
            {
                name = "AURA ✨",
                idleId = 125294976115462,
                moveId = 99148979036185,
                maxForwardPitch = 18,
